/// <summary>File convenience methods for the unbounded binary column accessors of OrderEntity (transfer blobs between the database and files in a single call; delegates to the Stream overloads).</summary>
public static class OrderRepositoryBinaryStreamExtensions
{
    /// <summary>Reads the payload column into a file (delegates to the Stream overload; true = written, false = no row or NULL, in which case an existing file is left untouched).</summary>
    public static async Task<bool> ReadPayloadToFileAsync(
        this IOrderRemoteRepository repository,
        OrderIdValue id,
        string path,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(repository);
        return await UnboundedBinaryColumns
            .ReadToFileAsync(path, destination => repository.ReadPayloadAsync(id, destination, cancellationToken))
            .ConfigureAwait(false);
    }

    /// <summary>Writes the payload column from a file (delegates to the Stream overload; true = updated, false = no row).</summary>
    public static async Task<bool> WritePayloadFromFileAsync(
        this IOrderRemoteRepository repository,
        OrderIdValue id,
        string path,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(repository);
        await using var source = File.OpenRead(path);
        return await repository.WritePayloadAsync(id, source, source.Length, cancellationToken).ConfigureAwait(false);
    }

    /// <summary>Reads the thumb column into a file (delegates to the Stream overload; true = written, false = no row or NULL, in which case an existing file is left untouched).</summary>
    public static async Task<bool> ReadThumbToFileAsync(
        this IOrderRemoteRepository repository,
        OrderIdValue id,
        string path,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(repository);
        return await UnboundedBinaryColumns
            .ReadToFileAsync(path, destination => repository.ReadThumbAsync(id, destination, cancellationToken))
            .ConfigureAwait(false);
    }

    /// <summary>Writes the thumb column from a file (delegates to the Stream overload; true = updated, false = no row).</summary>
    public static async Task<bool> WriteThumbFromFileAsync(
        this IOrderRemoteRepository repository,
        OrderIdValue id,
        string path,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(repository);
        await using var source = File.OpenRead(path);
        return await repository.WriteThumbAsync(id, source, source.Length, cancellationToken).ConfigureAwait(false);
    }
}

