/// <summary>Extensions that register the HTTP client implementations of the remote surface (I{Entity}RemoteRepository) with the DI container.</summary>
/// <remarks>
/// Each overload comes in a plain and a keyed form. Use the keyed one (<c>object? serviceKey</c>) to hold more than one
/// back end at a time - a remote server under one key and a local engine registered by
/// <c>AddGenerated{Dialect}Repositories(serviceKey, ...)</c> under another - and resolve them with
/// <c>[FromKeyedServices("...")]</c>.
/// </remarks>
public static class GeneratedHttpRemoteRepositoryServiceCollectionExtensions
{
    /// <summary>Registers the HTTP client implementations using a base address (for simple setups; the HttpClient is a shared singleton owned by the container).</summary>
    /// <remarks>
    /// <para>
    /// The shared HttpClient is owned by the DI container: it is created lazily, when a repository is first resolved,
    /// and disposed together with the <see cref="IServiceProvider"/>.
    /// </para>
    /// <para>
    /// Because its lifetime is bound to the container, a repository that was resolved from an already disposed provider
    /// throws <see cref="ObjectDisposedException"/> on use (the standard semantics for container-owned resources).
    /// To control the lifetime yourself, use the factory overload instead.
    /// </para>
    /// <para>
    /// The client it builds recycles pooled connections every five minutes
    /// (<see cref="SocketsHttpHandler.PooledConnectionLifetime"/>), so a long-lived singleton still follows DNS changes
    /// rather than pinning the address it first resolved.
    /// </para>
    /// <para>
    /// <b>It has no timeout of its own</b> (<see cref="Timeout.InfiniteTimeSpan"/>): the default of 100 seconds applies
    /// to a whole request including the body, which would cut off a large blob transfer part-way through. Bound each
    /// call with the <see cref="CancellationToken"/> you already pass to it - that is the timeout - or use the factory
    /// overload and hand in an HttpClient with whatever finite <see cref="HttpClient.Timeout"/> you want.
    /// </para>
    /// <para>
    /// Do not wrap this client in an HTTP-level retry policy that also retries the mutating operations
    /// (Insert / Update / Save / SaveMany / Delete); see the remarks on the factory overload.
    /// </para>
    /// </remarks>
    /// <param name="services">The service collection to register into</param>
    /// <param name="baseAddress">The base address including the server prefix - the one <c>MapGeneratedRemoteEndpoints</c> was mapped under, <see cref="RemotePaths.DefaultPrefix"/> unless it was passed another (for example <c>https://server:5001/quicker</c>; a trailing / is appended automatically)</param>
    public static IServiceCollection AddGeneratedHttpRemoteRepositories(
        this IServiceCollection services,
        string baseAddress
    )
    {
        ArgumentNullException.ThrowIfNull(services);
        ArgumentException.ThrowIfNullOrWhiteSpace(baseAddress);

        // A trailing / is required to resolve relative paths ("Order/GetById" etc.), so append it
        var normalized = baseAddress.EndsWith('/') ? baseAddress : baseAddress + "/";

        // Register a factory rather than a ready-made instance: the container disposes only the singletons it created
        // itself, so AddSingleton(instance) would leave the shared HttpClient undisposed when the provider is disposed
        services.AddSingleton(_ => new OwnedHttpClient(
            new HttpClient(
                new SocketsHttpHandler { PooledConnectionLifetime = TimeSpan.FromMinutes(5) },
                disposeHandler: true
            )
            {
                BaseAddress = new Uri(normalized),
                // No client-wide deadline: the 100-second default covers the entire request, body included, and would
                // abort a large blob upload or download. The per-call CancellationToken is the timeout instead
                Timeout = Timeout.InfiniteTimeSpan,
            }
        ));

        return AddGeneratedHttpRemoteRepositories(
            services,
            provider => provider.GetRequiredService<OwnedHttpClient>().Client
        );
    }

    /// <summary>Registers the HTTP client implementations using an HttpClient factory (when configuring authentication handlers etc.).</summary>
    /// <remarks>
    /// <para>
    /// The HttpClient returned by the factory must have a BaseAddress that includes the prefix and ends with a trailing /.
    /// </para>
    /// <para>
    /// Ownership contract: the factory is invoked every time a repository is resolved (once per scope and per entity),
    /// and the returned HttpClient is disposed by neither the generated code nor the DI container. Return a shared
    /// instance, or one managed by <c>IHttpClientFactory</c>; creating a new HttpClient on every call exhausts sockets.
    /// </para>
    /// <para>
    /// Do not attach an HTTP-level retry policy (Polly and the like) that resends the mutating operations - Insert,
    /// Update, Save, SaveMany, Delete. They carry no idempotency key, so a request that in fact succeeded and lost its
    /// response would be applied a second time. Retrying the read-only operations (GetById, GetAll, the named queries)
    /// and the health endpoint is safe.
    /// </para>
    /// </remarks>
    /// <param name="services">The service collection to register into</param>
    /// <param name="httpClientFactory">A factory returning the HttpClient to use when creating a repository</param>
    public static IServiceCollection AddGeneratedHttpRemoteRepositories(
        this IServiceCollection services,
        Func<IServiceProvider, HttpClient> httpClientFactory
    )
    {
        ArgumentNullException.ThrowIfNull(services);
        ArgumentNullException.ThrowIfNull(httpClientFactory);

        // Every entity is wired the same way: one client per scope over the HttpClient the factory hands back
        void AddClient<TRemote>(Func<HttpClient, TRemote> create)
            where TRemote : class =>
            services.AddScoped(provider => create(httpClientFactory(provider)));

        AddClient<ICustomerRemoteRepository>(client => new HttpCustomerRemoteRepository(client));
        AddClient<IOrderRemoteRepository>(client => new HttpOrderRemoteRepository(client));
        AddClient<IOrderLineRemoteRepository>(client => new HttpOrderLineRemoteRepository(client));

        return services;
    }

    /// <summary>Registers the HTTP client implementations under a service key using a base address (keyed DI, for talking to more than one back end at a time).</summary>
    /// <remarks>
    /// <para>
    /// Registers I{Entity}RemoteRepository keyed by <paramref name="serviceKey"/>. Consumers resolve the one they want
    /// like <c>[FromKeyedServices(serviceKey)] ICustomerRemoteRepository</c>. This is what a hybrid setup is built from:
    /// register the HTTP client under one key and a local engine (<c>AddGeneratedSqliteRepositories(key, ...)</c>) under
    /// another, and the same contract resolves to whichever side the caller asks for.
    /// </para>
    /// <para>
    /// The shared HttpClient is registered under the same key, so it collides with neither the non-keyed overload's client
    /// nor another key's, and stays owned by the DI container exactly as in the non-keyed overload: created lazily on the
    /// first resolve and disposed with the <see cref="IServiceProvider"/>. Registering the same key twice registers the
    /// repositories twice and the last one wins, which is how <c>AddKeyedScoped</c> behaves.
    /// </para>
    /// <para>
    /// The client is configured exactly as the non-keyed base-address overload configures it - connections recycled every
    /// five minutes, no client-wide timeout - and the same warning applies: do not put an HTTP-level retry policy in front
    /// of the mutating operations. See the remarks on the factory overload.
    /// </para>
    /// </remarks>
    /// <param name="services">The service collection to register into</param>
    /// <param name="serviceKey">The key the repositories (and the shared HttpClient) are registered under</param>
    /// <param name="baseAddress">The base address including the server prefix - the one <c>MapGeneratedRemoteEndpoints</c> was mapped under, <see cref="RemotePaths.DefaultPrefix"/> unless it was passed another (for example <c>https://server:5001/quicker</c>; a trailing / is appended automatically)</param>
    public static IServiceCollection AddGeneratedHttpRemoteRepositories(
        this IServiceCollection services,
        object? serviceKey,
        string baseAddress
    )
    {
        ArgumentNullException.ThrowIfNull(services);
        ArgumentException.ThrowIfNullOrWhiteSpace(baseAddress);

        // A trailing / is required to resolve relative paths ("Order/GetById" etc.), so append it
        var normalized = baseAddress.EndsWith('/') ? baseAddress : baseAddress + "/";

        // Keyed, and produced by a factory for the same reason the non-keyed overload uses one: the container disposes
        // only the singletons it created itself, and the key keeps this client apart from any other registration's
        services.AddKeyedSingleton(
            serviceKey,
            (_, _) => new OwnedHttpClient(
                new HttpClient(
                    new SocketsHttpHandler { PooledConnectionLifetime = TimeSpan.FromMinutes(5) },
                    disposeHandler: true
                )
                {
                    BaseAddress = new Uri(normalized),
                    // No client-wide deadline: the 100-second default covers the entire request, body included, and would
                    // abort a large blob upload or download. The per-call CancellationToken is the timeout instead
                    Timeout = Timeout.InfiniteTimeSpan,
                }
            )
        );

        return AddGeneratedHttpRemoteRepositories(
            services,
            serviceKey,
            provider => provider.GetRequiredKeyedService<OwnedHttpClient>(serviceKey).Client
        );
    }

    /// <summary>Registers the HTTP client implementations under a service key using an HttpClient factory (keyed DI, when configuring authentication handlers etc.).</summary>
    /// <remarks>
    /// <para>
    /// The keyed counterpart of the factory overload: the same ownership contract holds (the factory runs on every
    /// resolve and the HttpClient it returns is disposed by neither the generated code nor the container), and the same
    /// warning about retrying the mutating operations applies. Only the registration is keyed.
    /// </para>
    /// <para>
    /// Registering the same key twice registers the repositories twice and the last one wins. Keyed and non-keyed
    /// registrations do not see each other: a keyed registration answers only <c>GetRequiredKeyedService</c> with that
    /// key, and a plain <c>GetRequiredService</c> still needs a non-keyed one.
    /// </para>
    /// </remarks>
    /// <param name="services">The service collection to register into</param>
    /// <param name="serviceKey">The key the repositories are registered under</param>
    /// <param name="httpClientFactory">A factory returning the HttpClient to use when creating a repository</param>
    public static IServiceCollection AddGeneratedHttpRemoteRepositories(
        this IServiceCollection services,
        object? serviceKey,
        Func<IServiceProvider, HttpClient> httpClientFactory
    )
    {
        ArgumentNullException.ThrowIfNull(services);
        ArgumentNullException.ThrowIfNull(httpClientFactory);

        // Every entity is wired the same way: one client per scope, under the key this overload registers
        void AddClient<TRemote>(Func<HttpClient, TRemote> create)
            where TRemote : class =>
            services.AddKeyedScoped(serviceKey, (provider, _) => create(httpClientFactory(provider)));

        AddClient<ICustomerRemoteRepository>(client => new HttpCustomerRemoteRepository(client));
        AddClient<IOrderRemoteRepository>(client => new HttpOrderRemoteRepository(client));
        AddClient<IOrderLineRemoteRepository>(client => new HttpOrderLineRemoteRepository(client));

        return services;
    }

    /// <summary>Container-owned holder for the shared HttpClient created by a base-address overload.</summary>
    /// <remarks>
    /// Registering the holder as a singleton produced by a factory is what makes the DI container the owner:
    /// the container disposes the singletons it creates itself, so the wrapped HttpClient is disposed together
    /// with the <see cref="IServiceProvider"/>. The keyed overload registers the same holder under its key, so
    /// each key owns its own client and none of them collides with the non-keyed registration.
    /// </remarks>
    private sealed class OwnedHttpClient(HttpClient client) : IDisposable
    {
        /// <summary>Gets the shared client handed to the generated repositories.</summary>
        public HttpClient Client { get; } = client;

        /// <summary>Disposes the shared client (called by the DI container when the provider is disposed).</summary>
        public void Dispose() => Client.Dispose();
    }
}

/// <summary>One UNIQUE constraint of an entity type, resolved to the properties the in-memory store compares.</summary>
/// <param name="Name">The constraint's name (the synthesized name when the diagram does not set one).</param>
/// <param name="Properties">The entity properties that make up the constraint, in declaration order.</param>
internal sealed record InMemoryUniqueConstraint(
    string Name,
    IReadOnlyList<PropertyInfo> Properties
);

/// <summary>Enforcement of the UNIQUE constraints an entity type declares, standing in for the constraint a real database would hold.</summary>
/// <remarks>
/// <para>
/// The constraints are read once per type from the <see cref="UniqueConstraintAttribute"/> stamped on the entity class - the
/// same declaration the DDL creates and the repository's uniqueness pre-check walks - so the store rejects exactly the writes
/// the database would. The comparison rules are the pre-check's too: a tuple containing a null is not compared at all (what
/// NULL collides with differs per dialect), and the row being written is excluded by its primary key, so re-saving a row never
/// collides with itself. The user-defined checks (<c>CollectCustomUniquenessChecks</c>) are not enforced here; they are rules
/// of the application rather than constraints the database holds.
/// </para>
/// <para>
/// A violation is an <see cref="InvalidOperationException"/>, which is what a duplicate primary key already raises here. A real
/// database reports it through its own provider's exception instead - <c>SqlException</c> with error 2627, for one - and no
/// in-memory type can be that exception, so code that catches a provider exception has to be exercised against the database.
/// </para>
/// </remarks>
internal static class InMemoryUniqueness
{
    private static readonly ConcurrentDictionary<
        Type,
        IReadOnlyList<InMemoryUniqueConstraint>
    > _cache = new();

    /// <summary>The UNIQUE constraints declared on the entity type (empty when it declares none). Built once per type and cached.</summary>
    public static IReadOnlyList<InMemoryUniqueConstraint> For(Type entityType) =>
        _cache.GetOrAdd(entityType, Build);

    /// <summary>Throws when the row about to be written holds the same values as one of <paramref name="existing"/> on a declared UNIQUE constraint.</summary>
    /// <param name="entityType">The entity type being written.</param>
    /// <param name="row">The row about to be written.</param>
    /// <param name="key">The primary key of that row (the row carrying it is skipped, so an update never collides with itself).</param>
    /// <param name="existing">The rows to compare against, keyed by primary key.</param>
    public static void Verify(
        Type entityType,
        EntityBaseCore row,
        object key,
        IEnumerable<KeyValuePair<object, EntityBaseCore>> existing
    )
    {
        var constraints = For(entityType);

        if (constraints.Count == 0)
        {
            return;
        }

        // The written row's own tuples are read once rather than per row compared against
        object[]?[] tuples = new object[constraints.Count][];
        var comparable = false;

        for (var index = 0; index < constraints.Count; index++)
        {
            tuples[index] = ValuesOf(row, constraints[index]);
            comparable |= tuples[index] is not null;
        }

        if (!comparable)
        {
            return;
        }

        foreach (var (otherKey, other) in existing)
        {
            if (InMemoryKeyComparer.KeysEqual(otherKey, key))
            {
                continue;
            }

            for (var index = 0; index < constraints.Count; index++)
            {
                if (
                    tuples[index] is { } values
                    && ValuesOf(other, constraints[index]) is { } otherValues
                    && TupleEquals(values, otherValues)
                )
                {
                    throw DuplicateValueError(entityType, constraints[index], values);
                }
            }
        }
    }

    /// <summary>Creates the exception for a write that duplicates another row's values on a UNIQUE constraint.</summary>
    internal static InvalidOperationException DuplicateValueError(
        Type entityType,
        InMemoryUniqueConstraint constraint,
        object[] values
    ) =>
        new(
            $"Cannot write {entityType.Name} with {Describe(constraint, values)}: another row already holds these values, which violates the UNIQUE constraint '{constraint.Name}' (a real database would raise a unique-constraint violation)."
        );

    /// <summary>The constraint members and the values that collided, for the exception message.</summary>
    private static string Describe(InMemoryUniqueConstraint constraint, object[] values) =>
        string.Join(
            ", ",
            constraint.Properties.Select((property, index) => $"{property.Name} = '{values[index]}'")
        );

    /// <summary>The constraint's member values read off a row, or <c>null</c> when any of them is null (which takes the tuple out of the comparison).</summary>
    private static object[]? ValuesOf(EntityBaseCore row, InMemoryUniqueConstraint constraint)
    {
        var values = new object[constraint.Properties.Count];

        for (var index = 0; index < values.Length; index++)
        {
            if (constraint.Properties[index].GetValue(row) is not { } value)
            {
                return null;
            }

            values[index] = value;
        }

        return values;
    }

    /// <summary>Compares two member-value tuples element by element (a binary column by its content, a value object by its own equality).</summary>
    private static bool TupleEquals(object[] left, object[] right)
    {
        for (var index = 0; index < left.Length; index++)
        {
            if (!StructuralComparisons.StructuralEqualityComparer.Equals(left[index], right[index]))
            {
                return false;
            }
        }

        return true;
    }

    /// <summary>Builds an index of <paramref name="rows"/> on every UNIQUE constraint the type declares (<c>null</c> when it declares none).</summary>
    /// <remarks>
    /// A check that writes many rows at once - a bulk insert, the rows a graph save publishes - reads each row's values once
    /// into the index and looks every written row up in it, instead of comparing every written row against every row there
    /// is, which grew with the square of the row count.
    /// </remarks>
    /// <param name="entityType">The entity type the rows belong to.</param>
    /// <param name="rows">The rows to index, keyed by primary key.</param>
    internal static Index? BuildIndex(
        Type entityType,
        IEnumerable<KeyValuePair<object, EntityBaseCore>> rows
    )
    {
        var constraints = For(entityType);

        if (constraints.Count == 0)
        {
            return null;
        }

        var index = new Index(entityType, constraints);

        foreach (var (key, row) in rows)
        {
            index.Add(key, row);
        }

        return index;
    }

    /// <summary>The rows of one type indexed by their values on each declared UNIQUE constraint, applying the same comparison rules as <see cref="Verify"/>.</summary>
    internal sealed class Index
    {
        private readonly Type _entityType;
        private readonly IReadOnlyList<InMemoryUniqueConstraint> _constraints;
        private readonly Dictionary<object[], List<object>>[] _keysByValues;

        internal Index(Type entityType, IReadOnlyList<InMemoryUniqueConstraint> constraints)
        {
            _entityType = entityType;
            _constraints = constraints;
            _keysByValues = new Dictionary<object[], List<object>>[constraints.Count];

            for (var position = 0; position < constraints.Count; position++)
            {
                _keysByValues[position] = new Dictionary<object[], List<object>>(TupleComparer.Instance);
            }
        }

        /// <summary>Adds a row under its primary key (a tuple containing a null is not indexed, as it is not compared).</summary>
        public void Add(object key, EntityBaseCore row)
        {
            for (var position = 0; position < _constraints.Count; position++)
            {
                if (ValuesOf(row, _constraints[position]) is not { } values)
                {
                    continue;
                }

                if (!_keysByValues[position].TryGetValue(values, out var keys))
                {
                    keys = new List<object>(1);
                    _keysByValues[position].Add(values, keys);
                }

                keys.Add(key);
            }
        }

        /// <summary>Throws when a row other than the one under <paramref name="key"/> holds the same values as <paramref name="row"/> on a declared UNIQUE constraint.</summary>
        public void Verify(object key, EntityBaseCore row)
        {
            for (var position = 0; position < _constraints.Count; position++)
            {
                if (
                    ValuesOf(row, _constraints[position]) is { } values
                    && _keysByValues[position].TryGetValue(values, out var keys)
                    && keys.Exists(other => !InMemoryKeyComparer.KeysEqual(other, key))
                )
                {
                    throw DuplicateValueError(_entityType, _constraints[position], values);
                }
            }
        }
    }

    /// <summary>Compares member-value tuples the way <see cref="TupleEquals"/> does, with a hash code consistent with it.</summary>
    private sealed class TupleComparer : IEqualityComparer<object[]>
    {
        public static readonly TupleComparer Instance = new();

        public bool Equals(object[]? x, object[]? y) =>
            ReferenceEquals(x, y) || (x is not null && y is not null && TupleEquals(x, y));

        public int GetHashCode(object[] obj)
        {
            var hash = new HashCode();

            foreach (var value in obj)
            {
                hash.Add(StructuralComparisons.StructuralEqualityComparer.GetHashCode(value));
            }

            return hash.ToHashCode();
        }
    }

    /// <summary>Resolves the constraints declared on an entity type (a constraint naming a property the type does not have is dropped, as one whose columns cannot all be resolved is never generated).</summary>
    private static IReadOnlyList<InMemoryUniqueConstraint> Build(Type entityType)
    {
        var constraints = new List<InMemoryUniqueConstraint>();

        foreach (var attribute in entityType.GetCustomAttributes<UniqueConstraintAttribute>())
        {
            var properties = new List<PropertyInfo>(attribute.PropertyNames.Length);

            foreach (var propertyName in attribute.PropertyNames)
            {
                if (
                    entityType.GetProperty(
                        propertyName,
                        BindingFlags.Public | BindingFlags.Instance
                    )
                        is { } property
                )
                {
                    properties.Add(property);
                }
            }

            if (properties.Count > 0 && properties.Count == attribute.PropertyNames.Length)
            {
                constraints.Add(new InMemoryUniqueConstraint(attribute.Name, properties));
            }
        }

        return constraints;
    }
}

/// <summary>Compares the primary keys the in-memory store files rows under.</summary>
/// <remarks>
/// A key is compared the way a database compares the column: a binary key (<c>binary(n)</c>, a <c>byte[]</c>) by its
/// bytes, everything else by its own equality. The default comparer would compare a <c>byte[]</c> by reference, and the
/// store hands out copies of every array, so a binary key read back from the store would never find its own row again.
/// </remarks>
internal sealed class InMemoryKeyComparer
    : IEqualityComparer<object>,
        IEqualityComparer<(Type EntityType, object Key)>
{
    /// <summary>The shared instance (the comparer holds no state).</summary>
    public static readonly InMemoryKeyComparer Instance = new();

    private InMemoryKeyComparer() { }

    /// <summary>Whether two keys identify the same row.</summary>
    public static bool KeysEqual(object? x, object? y) =>
        x is byte[] left && y is byte[] right ? left.AsSpan().SequenceEqual(right) : Equals(x, y);

    /// <summary>The hash code of a key, consistent with <see cref="KeysEqual"/>.</summary>
    public static int KeyHashCode(object key)
    {
        if (key is byte[] bytes)
        {
            var hash = new HashCode();
            hash.AddBytes(bytes);
            return hash.ToHashCode();
        }

        return key.GetHashCode();
    }

    bool IEqualityComparer<object>.Equals(object? x, object? y) => KeysEqual(x, y);

    int IEqualityComparer<object>.GetHashCode(object obj) => KeyHashCode(obj);

    bool IEqualityComparer<(Type EntityType, object Key)>.Equals(
        (Type EntityType, object Key) x,
        (Type EntityType, object Key) y
    ) => x.EntityType == y.EntityType && KeysEqual(x.Key, y.Key);

    int IEqualityComparer<(Type EntityType, object Key)>.GetHashCode(
        (Type EntityType, object Key) obj
    ) => HashCode.Combine(obj.EntityType, KeyHashCode(obj.Key));
}

/// <summary>
/// In-memory data store that holds entities in memory without a database (shared as a DI singleton).
/// </summary>
/// <remarks>
/// <para>
/// Keeps a "primary key -> snapshot" dictionary per entity type. A write files away a copy of the entity's columns and a
/// read hands out another copy of the stored row's columns, so mutating a returned entity on the caller
/// side never changes the store contents (matching the by-value semantics of a real database). All operations are
/// serialized with a <c>lock</c> to be thread-safe.
/// </para>
/// <para>
/// The primary key is taken from <see cref="EntitySaveMetadata.KeyProperty"/>, and value objects are opened to their
/// underlying value to form the dictionary key (so they match by value equality). Keys are compared by
/// <see cref="InMemoryKeyComparer"/>, which compares a binary key (<c>binary(n)</c>) by its bytes.
/// </para>
/// </remarks>
public sealed class InMemoryDataStore
{
    private readonly object _gate = new();
    private readonly Dictionary<Type, Dictionary<object, EntityBaseCore>> _tables = new();
    private long _rowVersion;

    /// <summary>Gets the table (primary key -> snapshot) for the given type, creating it if absent. The caller must already hold the lock.</summary>
    private Dictionary<object, EntityBaseCore> Table(Type entityType)
    {
        if (!_tables.TryGetValue(entityType, out var table))
        {
            table = new Dictionary<object, EntityBaseCore>(InMemoryKeyComparer.Instance);
            _tables[entityType] = table;
        }

        return table;
    }

    /// <summary>Normalizes an entity's primary key value into a dictionary key (value objects are opened to their underlying value; null is not allowed).</summary>
    internal static object KeyOf(EntityBaseCore entity)
    {
        var metadata = EntitySaveMetadata.For(entity.GetType());
        var raw = metadata.KeyProperty.GetValue(entity);
        raw = raw is IValueObjectCore vo ? vo.UnderlyingValue : raw;

        return raw
            ?? throw new InvalidOperationException(
                $"The primary key of {entity.GetType().Name} is null. In-memory persistence requires a primary key value."
            );
    }

    /// <summary>Gets all snapshots of the given type (as clones).</summary>
    /// <remarks>The returned clones drop unbounded binary columns to their "not fetched" state (matching the real database's SELECT exclusion; the store's actual data is preserved).</remarks>
    public IReadOnlyList<TEntity> Snapshot<TEntity>()
        where TEntity : EntityBaseCore, new()
    {
        lock (_gate)
        {
            return Table(typeof(TEntity)).Values.Select(entity => CopyRow<TEntity>(entity)).ToList();
        }
    }

    /// <summary>Gets the snapshot for the given type and primary key (as a clone; null if not found).</summary>
    /// <remarks>The returned clone drops unbounded binary columns to their "not fetched" state (matching the real database's SELECT exclusion; the store's actual data is preserved).</remarks>
    public TEntity? Find<TEntity>(object key)
        where TEntity : EntityBaseCore, new()
    {
        lock (_gate)
        {
            if (!Table(typeof(TEntity)).TryGetValue(key, out var entity))
            {
                return null;
            }

            return CopyRow<TEntity>(entity);
        }
    }

    /// <summary>
    /// Assigns the next store-generated row version to <paramref name="snapshot"/> and returns the rowversion property that
    /// was stamped (<c>null</c> for a type without a rowversion column, in which case nothing was assigned).
    /// </summary>
    /// <remarks>
    /// The value is a monotonically increasing 8-byte big-endian token that emulates SQL Server's rowversion: every insert
    /// and update moves it on, so an entity holding a stale version can be told apart from a current one. The counter is
    /// advanced atomically because a save hook's After writes a column outside the store lock.
    /// </remarks>
    private PropertyInfo? StampRowVersion(EntityBaseCore snapshot)
    {
        var property = EntitySaveMetadata.For(snapshot.GetType()).RowVersionProperty;

        if (property is null)
        {
            return null;
        }

        var version = BitConverter.GetBytes(Interlocked.Increment(ref _rowVersion));

        // Big-endian so that comparing the bytes orders the versions the same way as comparing the numbers
        if (BitConverter.IsLittleEndian)
        {
            Array.Reverse(version);
        }

        property.SetValue(snapshot, SqlValueObjectActivator.Wrap(version, property.PropertyType));
        return property;
    }

    /// <summary>Stamps <paramref name="snapshot"/> and hands the newly assigned version straight to <paramref name="source"/> (used by the writes that apply to the store immediately).</summary>
    private void StampRowVersionDirect(EntityBaseCore snapshot, EntityBaseCore? source)
    {
        var property = StampRowVersion(snapshot);

        if (property is null || source is null)
        {
            return;
        }

        ApplyRowVersion(source, property, snapshot);
    }

    /// <summary>Copies the row version a stored snapshot holds onto the caller's entity, mirroring how a real database hands the newly assigned version back.</summary>
    /// <remarks>The caller's entity gets its own array so that mutating one side cannot reach into the store's snapshot.</remarks>
    private static void ApplyRowVersion(
        EntityBaseCore source,
        PropertyInfo property,
        EntityBaseCore snapshot
    )
    {
        var stored = SqlParameterValue.Unwrap(property.GetValue(snapshot));

        if (stored is byte[] version)
        {
            property.SetValue(source, SqlValueObjectActivator.Wrap(version.ToArray(), property.PropertyType));
        }
    }

    /// <summary>Copies the columns of <paramref name="entity"/> onto a fresh instance of its type, leaving the navigations at the values the constructor gives them (an empty collection, a null reference).</summary>
    /// <remarks>
    /// <para>
    /// The store holds rows, not graphs. A graph handed to a save would otherwise be filed away with its children still
    /// hanging off the row - and still marked Added - whereas a real database stores rows: a fetch without Include comes back
    /// with its navigations empty, and re-saving what it returned does not try to insert the children a second time. Nothing
    /// is lost on the read side, where Include rebuilds the navigations from the child rows whenever a query asks for them.
    /// </para>
    /// <para>
    /// Copying the columns alone is also what keeps a save linear. <see cref="EntityBaseCore.Clone"/> deep-copies the whole
    /// subtree (a JSON round trip) only for the children to be dropped again straight afterwards, so saving a graph of n
    /// nodes copied the subtree of every one of them.
    /// </para>
    /// <para>
    /// A binary column is copied rather than shared, because it is the one column value that can be mutated in place; that
    /// keeps the by-value semantics cloning gave, where writing through the caller's array cannot reach the store's row.
    /// </para>
    /// </remarks>
    /// <param name="entity">The entity whose columns are copied.</param>
    /// <param name="includeUnboundedBinary">
    /// Whether the unbounded binary columns are copied as well. When they are not, the copy keeps the values the constructor
    /// gives them - the "not fetched" state a real database's SELECT leaves them in - and the blob is never read at all.
    /// </param>
    private static EntityBaseCore CopyColumns(EntityBaseCore entity, bool includeUnboundedBinary = true)
    {
        var entityType = entity.GetType();
        var copy = (EntityBaseCore)Activator.CreateInstance(entityType)!;
        var metadata = EntitySaveMetadata.For(entityType);

        foreach (var property in includeUnboundedBinary ? metadata.AllProperties : metadata.SelectProperties)
        {
            var value = property.GetValue(entity);

            // A binary value object hands out the very array it was created with, so the copy has to reach inside it
            if (value is IValueObjectCore valueObject && valueObject.UnderlyingValue is byte[] wrapped)
            {
                value = SqlValueObjectActivator.Wrap(
                    (byte[])wrapped.Clone(),
                    property.PropertyType
                );
            }

            // Copy arrays rather than share them: byte[] binary columns and array columns
            // (such as PostgreSQL integer[]) would otherwise be the same instance in the store
            // and in the caller's entity, so a later mutation would silently change the stored row.
            property.SetValue(copy, value is Array array ? array.Clone() : value);
        }

        return copy;
    }

    /// <summary>Copies a stored row for a reader: its columns only, marked Unchanged.</summary>
    /// <remarks>
    /// The unbounded binary columns are left in their "not fetched" state unless <paramref name="includeUnboundedBinary"/>
    /// asks for them, matching a real database's SELECT that does not name them. Leaving them out of the copy, rather than
    /// copying them and dropping them again afterwards, is what keeps a read of a row holding a large blob from moving the
    /// blob at all.
    /// </remarks>
    internal static TEntity CopyRow<TEntity>(EntityBaseCore row, bool includeUnboundedBinary = false)
        where TEntity : EntityBaseCore
    {
        var copy = CopyColumns(row, includeUnboundedBinary);
        copy.MarkUnchanged();
        return (TEntity)copy;
    }

    /// <summary>Prepares the snapshot to store for <paramref name="entity"/>: a detached row carrying over whatever the row being replaced holds in columns this write does not name.</summary>
    /// <remarks>
    /// <paramref name="previous"/> is the row this write replaces (<c>null</c> for an insert, which writes every column just
    /// as a real INSERT does).
    /// </remarks>
    private static EntityBaseCore PrepareSnapshot(EntityBaseCore entity, EntityBaseCore? previous)
    {
        var snapshot = CopyColumns(entity);

        if (previous is not null)
        {
            UnboundedBinaryColumns.PreserveUnset(snapshot, previous);
        }

        snapshot.MarkUnchanged();
        return snapshot;
    }

    /// <summary>Gets the raw snapshot (no clone) for the given type and primary key. Used by internal traversals such as Include key matching. The caller must already hold the lock.</summary>
    private EntityBaseCore? FindRaw(Type entityType, object key) =>
        Table(entityType).TryGetValue(key, out var entity) ? entity : null;

    /// <summary>Gets the list of raw snapshots (no clones) for the given type. Used by the query executor's internal traversals. The caller must already hold the lock.</summary>
    private IReadOnlyList<EntityBaseCore> RawAll(Type entityType) => Table(entityType).Values.ToList();

    /// <summary>Gets the list of raw snapshots (no clones) for the given type. Used inside the lock to hand pre-clone snapshots to the executor.</summary>
    internal IReadOnlyList<EntityBaseCore> RawSnapshotUnlocked(Type entityType) => RawAll(entityType);

    /// <summary>Runs an arbitrary read traversal over the whole store under the lock (so Include key matching can span multiple tables).</summary>
    internal TResult Read<TResult>(Func<InMemoryReadScope, TResult> reader)
    {
        lock (_gate)
        {
            return reader(new InMemoryReadScope(this));
        }
    }

    /// <summary>Stores a snapshot (clone) for updates and seeding (an existing key is overwritten). Use <see cref="Insert"/> for inserts, which reject an existing key.</summary>
    internal void Put(EntityBaseCore entity)
    {
        lock (_gate)
        {
            var table = Table(entity.GetType());
            var key = KeyOf(entity);
            var snapshot = PrepareSnapshot(entity, table.GetValueOrDefault(key));
            StampRowVersionDirect(snapshot, entity);
            table[key] = snapshot;
        }
    }

    /// <summary>Creates the exception for an insert that hits an existing primary key (mirroring the primary-key violation a real database would raise).</summary>
    internal static InvalidOperationException DuplicateKeyError(Type entityType, object key) =>
        new(
            $"Cannot insert {entityType.Name} with key '{key}': an entity with the same primary key already exists (a real database would raise a primary-key violation)."
        );

    /// <summary>Stores a snapshot (clone) for an insert only. An existing primary key is rejected with an <see cref="InvalidOperationException"/> instead of being silently overwritten.</summary>
    /// <remarks>The declared UNIQUE constraints are checked as well, before anything is written, so a rejected insert leaves the store untouched.</remarks>
    internal void Insert(EntityBaseCore entity)
    {
        lock (_gate)
        {
            var entityType = entity.GetType();
            var key = KeyOf(entity);
            var snapshot = PrepareSnapshot(entity, previous: null);
            InMemoryUniqueness.Verify(entityType, snapshot, key, Table(entityType));

            if (!Table(entity.GetType()).TryAdd(key, snapshot))
            {
                throw DuplicateKeyError(entity.GetType(), key);
            }

            // Stamped only once the row is in, so a rejected insert consumes no version and leaves the entity untouched
            StampRowVersionDirect(snapshot, entity);
        }
    }

    /// <summary>Removes the snapshot for the given type and primary key (true if one existed).</summary>
    internal bool Remove(Type entityType, object key)
    {
        lock (_gate)
        {
            return Table(entityType).Remove(key);
        }
    }

    /// <summary>
    /// Reads a column value for the given type and primary key without stripping (used by the streaming accessors for unbounded binary columns).
    /// Returns the store's raw value (without going through the read-clone strip, so the excluded column's actual data is available).
    /// </summary>
    internal object? ReadColumnValue(
        Type entityType,
        object key,
        PropertyInfo column,
        out bool rowExists
    )
    {
        lock (_gate)
        {
            var entity = FindRaw(entityType, key);
            rowExists = entity is not null;
            return entity is null ? null : column.GetValue(entity);
        }
    }

    /// <summary>
    /// Rewrites a column value for the given type and primary key (used by the streaming accessors for unbounded binary columns; true if the row existed).
    /// Does not mutate the store's actual entity directly; instead it updates a clone and writes it back (following the existing Clone/Put semantics).
    /// </summary>
    /// <remarks>
    /// The row version moves on, mirroring the real database where writing a blob is an UPDATE like any other. A standalone
    /// call has no caller entity to hand the new version back to, so an entity fetched before it is left holding a stale
    /// version. When <paramref name="staging"/> is given (a write from a save hook's After), the write joins the save's
    /// staging instead of touching the store: it builds on what the save has already staged for the row, stays invisible
    /// until the save publishes, and the version it assigns is the one the caller's entity ends up with.
    /// </remarks>
    internal bool WriteColumnValue(
        Type entityType,
        object key,
        PropertyInfo column,
        object? value,
        InMemorySaveStaging? staging = null
    )
    {
        if (staging is null)
        {
            lock (_gate)
            {
                var entity = FindRaw(entityType, key);

                if (entity is null)
                {
                    return false;
                }

                var clone = CopyRow<EntityBaseCore>(entity, includeUnboundedBinary: true);
                column.SetValue(clone, value);
                clone.MarkUnchanged();
                StampRowVersion(clone);
                Table(entityType)[key] = clone;
                return true;
            }
        }

        EntityBaseCore? baseRow;

        lock (_gate)
        {
            baseRow = FindRaw(entityType, key);
        }

        // A row the save has already staged wins over the store's own row (the save's own writes are visible to its hooks)
        var current = staging.TryGetStaged(entityType, key, out var staged) ? staged : baseRow;

        if (current is null)
        {
            return false;
        }

        staging.CaptureBase(entityType, key, baseRow);
        var updated = CopyRow<EntityBaseCore>(current, includeUnboundedBinary: true);
        column.SetValue(updated, value);
        updated.MarkUnchanged();
        StampRowVersion(updated);
        staging.Stage(entityType, key, updated);
        return true;
    }

    /// <summary>Applies multiple writes (insert/update/delete) together under a single lock (preserving the atomicity of a graph save).</summary>
    internal TResult Write<TResult>(Func<InMemoryWriteScope, TResult> writer) =>
        Write(writer, staging: null);

    /// <summary>
    /// Runs multiple writes together under a single lock. Without <paramref name="staging"/> the writes are applied to the
    /// store as they happen; with it they are staged instead and only become visible once <see cref="Publish"/> accepts them,
    /// which is what lets a graph save stay all-or-nothing across the phases that run outside the lock.
    /// </summary>
    /// <remarks>
    /// A failure part-way through simply lets the exception out: the staging is the only place the writes exist, so the
    /// caller discarding it is all the rollback there is (nothing was ever applied to the store).
    /// </remarks>
    internal TResult Write<TResult>(
        Func<InMemoryWriteScope, TResult> writer,
        InMemorySaveStaging? staging
    )
    {
        lock (_gate)
        {
            return writer(new InMemoryWriteScope(this, staging));
        }
    }

    /// <summary>
    /// Publishes everything a save staged, under the lock, after verifying that nobody else has written the rows the save
    /// started from.
    /// </summary>
    /// <remarks>
    /// <para>
    /// The verification is what makes the copy-on-write scheme safe. The staged writes were prepared against the rows the
    /// save read while it held the lock, and the save hooks' After runs outside the lock in between, so another thread may
    /// have written the same rows meanwhile. Every row the save touched is therefore compared against the snapshot it
    /// started from; reference equality is enough because the store never hands its snapshots out and replaces them
    /// wholesale on every write.
    /// </para>
    /// <para>
    /// Whether the row is still there is settled first, and independently of the concurrency policy and of whether the type
    /// carries a rowversion column at all, because a version comparison against a row that no longer exists cannot say
    /// anything about it. Last-write-wins stops short of resurrection: a row the save started from that has been deleted
    /// meanwhile cannot be written back, because putting the staged snapshot in would bring a deleted row to life, where a
    /// real database's UPDATE simply affects no rows. Reporting that as <see cref="SaveConflictReason.NotFound"/> is what
    /// keeps the save honest: the row count the save already returned counted this write, and its entities are about to be
    /// accepted as saved, so dropping the write silently would leave the caller believing a row exists that does not. A
    /// staged delete for such a row is not a conflict (deleting a row that is already gone is the same no-op it is against a
    /// real database). This is the same split a real backend makes when its UPDATE affects no rows and it asks whether the
    /// row exists before deciding between "gone" and "changed". <see cref="ConcurrencyMode.ForceOverwrite"/> does not lift
    /// this: it waives the version comparison, not the existence check, so a staged update against a row that was deleted
    /// meanwhile still fails.
    /// </para>
    /// <para>
    /// <c>insertWhenUpdateMissing</c> does not reach here either. The save phase decides between an UPDATE and the fallback
    /// INSERT while it holds the lock, so a row deleted after that decision leaves the save holding a staged update and this
    /// verification reports <see cref="SaveConflictReason.NotFound"/> rather than turning the write into an insert. A real
    /// database has no window in which that could happen - its own statement sees the row's absence at the moment it writes -
    /// so this is a divergence of the in-memory backend rather than a rule it shares.
    /// </para>
    /// <para>
    /// Only a row that is still there has its version compared. A row whose type has no rowversion column is not verified:
    /// without a concurrency token the store's contract is last-write-wins, exactly as it is for a direct update, and
    /// <see cref="ConcurrencyMode.ForceOverwrite"/> waives the verification for the same reason. A row the save inserted is
    /// verified whatever the mode, because someone else having taken the same primary key meanwhile is a duplicate key
    /// rather than something an overwrite policy can excuse.
    /// </para>
    /// <para>
    /// A delete the save staged for a row that did not exist when the save reached it is neither verified nor applied. A
    /// row standing under that key at publishing time was put there by someone else meanwhile, and removing it would
    /// delete a row the save never saw, where a real database's DELETE affected no rows at the moment it ran.
    /// </para>
    /// <para>
    /// Once every row has been verified, the declared UNIQUE constraints are verified as well, over the state publishing is
    /// about to leave the store in (see <see cref="VerifyStagedUniqueness"/>). That check comes last because it is about the
    /// values the save is writing rather than about who else has written meanwhile, and it comes before anything is applied,
    /// so a violation drops the save whole.
    /// </para>
    /// <para>
    /// Once the writes are in, the row versions they assigned are read back out of the published snapshots and handed to the
    /// caller's entities. Reading them back (rather than remembering them when they were assigned) is what keeps a later
    /// write to the same row - a hook writing a blob, for instance - from leaving the caller holding a superseded version.
    /// </para>
    /// </remarks>
    internal void Publish(InMemorySaveStaging staging, ConcurrencyMode mode)
    {
        lock (_gate)
        {
            foreach (var (entityType, key, baseRow) in staging.Baseline)
            {
                var current = Table(entityType).GetValueOrDefault(key);

                if (ReferenceEquals(current, baseRow))
                {
                    continue;
                }

                if (baseRow is null)
                {
                    // The save is adding this row, but the primary key has been taken since: a real database would raise
                    // the primary-key violation at this point, and no concurrency policy makes that acceptable.
                    if (staging.Staged(entityType, key) is not null)
                    {
                        throw DuplicateKeyError(entityType, key);
                    }

                    // A delete of a row that did not exist when the save reached it: the row there now was written by
                    // someone else meanwhile, so it is neither a conflict nor this save's to remove (applying is skipped
                    // below as well), just as a real database's DELETE affected no rows at the moment it ran.
                    continue;
                }

                // The row this write started from is gone. Whether it is still there is settled before whether its version
                // still matches, because a version comparison against a row that no longer exists cannot say anything:
                // overwriting last-write-wins does not extend to reviving it, and saying so beats dropping the write, which
                // would report a saved row that is not there. A staged delete against an already deleted row stays the no-op
                // it is against a real database, whether or not the type carries a rowversion column.
                if (current is null)
                {
                    // "Staged a delete" is an entry holding a null snapshot, not the absence of an entry: a save that
                    // captured this row without ever writing to it has nothing to revive, and reading the two as one
                    // would let such a capture pass for a delete
                    if (staging.TryGetStaged(entityType, key, out var staged) && staged is null)
                    {
                        continue;
                    }

                    throw SaveConflictException.NotFound(entityType, key);
                }

                if (
                    mode == ConcurrencyMode.Optimistic
                    && EntitySaveMetadata.For(entityType).RowVersionProperty is not null
                )
                {
                    throw SaveConflictException.Modified(entityType, key, "save");
                }
            }

            VerifyStagedUniqueness(staging);

            foreach (var ((entityType, key), snapshot) in staging.Overlay)
            {
                if (snapshot is not null)
                {
                    Table(entityType)[key] = snapshot;
                }
                else if (!staging.StartedWithoutRow(entityType, key))
                {
                    // A delete removes only a row the save started from: had the row been absent then, whatever stands
                    // under the key now (another writer's insert) is not the row the save deleted
                    Table(entityType).Remove(key);
                }
            }

            foreach (var (source, property, entityType, key) in staging.Stamps)
            {
                if (Table(entityType).GetValueOrDefault(key) is { } published)
                {
                    ApplyRowVersion(source, property, published);
                }
            }
        }
    }

    /// <summary>Verifies the declared UNIQUE constraints of every row a save staged, against the state publishing is about to leave the store in.</summary>
    /// <remarks>
    /// The comparison runs over the composed view - the store's rows with the save's own inserts, updates and deletes applied -
    /// so a save sees its own writes: two rows it adds with the same values collide with each other, and a value it frees by
    /// deleting a row is available to a row it adds in the same save. Judging the outcome rather than the order the graph
    /// walker happened to reach the rows in is what makes the verdict independent of that order. It runs before anything is
    /// applied, so a violation leaves the save all-or-nothing exactly as a version conflict does. The view of each type is
    /// indexed once and every staged row is looked up in the index, so the check grows with the rows rather than with their
    /// square.
    /// </remarks>
    private void VerifyStagedUniqueness(InMemorySaveStaging staging)
    {
        Dictionary<Type, InMemoryUniqueness.Index>? indexes = null;

        foreach (var ((entityType, key), snapshot) in staging.Overlay)
        {
            // A staged delete removes a row rather than adding values, and a type without constraints has nothing to compare
            if (snapshot is null || InMemoryUniqueness.For(entityType).Count == 0)
            {
                continue;
            }

            indexes ??= new Dictionary<Type, InMemoryUniqueness.Index>();

            if (!indexes.TryGetValue(entityType, out var index))
            {
                index = InMemoryUniqueness.BuildIndex(entityType, ComposeView(entityType, staging))!;
                indexes.Add(entityType, index);
            }

            index.Verify(key, snapshot);
        }
    }

    /// <summary>The rows of one type as publishing will leave them: the store's rows with the save's staged writes applied.</summary>
    private Dictionary<object, EntityBaseCore> ComposeView(
        Type entityType,
        InMemorySaveStaging staging
    )
    {
        var view = new Dictionary<object, EntityBaseCore>(Table(entityType), InMemoryKeyComparer.Instance);

        foreach (var ((stagedType, key), snapshot) in staging.Overlay)
        {
            if (stagedType != entityType)
            {
                continue;
            }

            if (snapshot is null)
            {
                view.Remove(key);
            }
            else
            {
                view[key] = snapshot;
            }
        }

        return view;
    }

    /// <summary>Clears all tables (for resetting in tests).</summary>
    public void Clear()
    {
        lock (_gate)
        {
            _tables.Clear();
        }
    }

    /// <summary>Scope for reading across multiple tables under the lock (used for Include key matching).</summary>
    internal readonly struct InMemoryReadScope(InMemoryDataStore store)
    {
        /// <summary>The list of raw snapshots (no clones) for the given type.</summary>
        public IReadOnlyList<EntityBaseCore> All(Type entityType) => store.RawAll(entityType);

        /// <summary>The raw snapshot (no clone) for the given type and primary key (null if not found).</summary>
        public EntityBaseCore? Find(Type entityType, object key) => store.FindRaw(entityType, key);
    }

    /// <summary>
    /// Scope for applying writes across a whole graph under the lock. Without a staging the writes land in the store
    /// straight away; with one they are staged and read back through the staging, so the save sees its own writes while
    /// nobody else does until it publishes.
    /// </summary>
    internal readonly struct InMemoryWriteScope(
        InMemoryDataStore store,
        InMemorySaveStaging? staging
    )
    {
        /// <summary>The row as this scope sees it: what the save has staged for it, or else the store's own row (null when there is none).</summary>
        private EntityBaseCore? Current(Type entityType, object key) =>
            staging is not null && staging.TryGetStaged(entityType, key, out var staged)
                ? staged
                : store.FindRaw(entityType, key);

        /// <summary>Applies or stages a prepared snapshot and arranges for the newly assigned row version to reach <paramref name="entity"/>.</summary>
        private void Write(EntityBaseCore entity, Type entityType, object key, EntityBaseCore snapshot)
        {
            if (staging is null)
            {
                store.StampRowVersionDirect(snapshot, entity);
                store.Table(entityType)[key] = snapshot;
                return;
            }

            // The first touch of a row records the baseline that publishing verifies against
            staging.CaptureBase(entityType, key, store.FindRaw(entityType, key));
            var property = store.StampRowVersion(snapshot);
            staging.Stage(entityType, key, snapshot);

            if (property is not null)
            {
                // Only the row is remembered, not the version: the version handed over is whichever one gets published
                staging.RecordStamp(entity, property, entityType, key);
            }
        }

        /// <summary>Stores a snapshot for updates and seeding (an existing key is overwritten). Assumes the lock is held, so it writes directly to the internal dictionary.</summary>
        public void Put(EntityBaseCore entity)
        {
            var entityType = entity.GetType();
            var key = KeyOf(entity);
            var snapshot = PrepareSnapshot(entity, Current(entityType, key));
            Write(entity, entityType, key, snapshot);
        }

        /// <summary>Stores a snapshot for an insert only (an existing primary key throws instead of being overwritten). Assumes the lock is held, so it writes directly to the internal dictionary.</summary>
        public void Insert(EntityBaseCore entity)
        {
            var entityType = entity.GetType();
            var key = KeyOf(entity);

            // Rejected before anything is written, so a rejected insert consumes no version and leaves the entity untouched
            if (Exists(entityType, key))
            {
                throw DuplicateKeyError(entityType, key);
            }

            var snapshot = PrepareSnapshot(entity, previous: null);
            Write(entity, entityType, key, snapshot);
        }

        /// <summary>Removes the snapshot for the given type and primary key (true if one existed).</summary>
        public bool Remove(Type entityType, object key)
        {
            if (staging is null)
            {
                return store.Table(entityType).Remove(key);
            }

            var existed = Current(entityType, key) is not null;
            staging.CaptureBase(entityType, key, store.FindRaw(entityType, key));
            staging.Stage(entityType, key, null);
            return existed;
        }

        /// <summary>Whether a snapshot exists for the given type and primary key.</summary>
        public bool Exists(Type entityType, object key) => Current(entityType, key) is not null;

        /// <summary>Verifies the declared UNIQUE constraints of a row about to be written, against the store's rows.</summary>
        /// <remarks>
        /// This is the direct writes' check, made before the write so that a rejection leaves nothing behind. A graph save's
        /// rows are not checked here but as a whole when the save publishes, so that a save which frees a value on one row and
        /// takes it on another is judged by the state it leaves behind rather than by the order its writes happened in.
        /// </remarks>
        /// <param name="entity">The row about to be written.</param>
        /// <param name="key">The primary key of that row (the row carrying it is skipped, so an update never collides with itself).</param>
        public void VerifyUnique(EntityBaseCore entity, object key)
        {
            var entityType = entity.GetType();
            InMemoryUniqueness.Verify(entityType, entity, key, store.Table(entityType));
        }

        /// <summary>Indexes the store's rows of the given type on its declared UNIQUE constraints (<c>null</c> when it declares none), for a check that writes many rows at once.</summary>
        public InMemoryUniqueness.Index? UniquenessIndex(Type entityType) =>
            InMemoryUniqueness.BuildIndex(entityType, store.Table(entityType));

        /// <summary>
        /// Whether <paramref name="entity"/> may overwrite the stored row under the given concurrency policy: <c>true</c> when
        /// the type has no rowversion column, when the policy is <see cref="ConcurrencyMode.ForceOverwrite"/>, when there is no
        /// stored row at all (a missing row is the caller's decision to make), or when the entity still carries the version the
        /// stored row has.
        /// </summary>
        /// <remarks>
        /// The comparison is strict: an entity whose version is null (never read back from the store) never matches a stored
        /// row, which is what a real database does with <c>WHERE ... AND row_ver = @originalRowVersion</c>.
        /// </remarks>
        public bool IsCurrent(EntityBaseCore entity, ConcurrencyMode mode)
        {
            var property = EntitySaveMetadata.For(entity.GetType()).RowVersionProperty;

            if (property is null || mode != ConcurrencyMode.Optimistic)
            {
                return true;
            }

            var stored = Current(entity.GetType(), KeyOf(entity));

            if (stored is null)
            {
                return true;
            }

            return SqlParameterValue.Unwrap(property.GetValue(entity)) is byte[] carried
                && SqlParameterValue.Unwrap(property.GetValue(stored)) is byte[] current
                && carried.SequenceEqual(current);
        }

        /// <summary>The list of raw snapshots (no clones) for the given type. Used by the descendant traversal for cascade delete.</summary>
        public IReadOnlyList<EntityBaseCore> All(Type entityType) => store.RawAll(entityType);
    }
}

/// <summary>
/// Copy-on-write staging area holding the writes of one graph save, so that the whole save unit is all-or-nothing even
/// though the <see cref="InMemoryDataStore"/> has no real transaction of its own.
/// </summary>
/// <remarks>
/// <para>
/// A staged write is invisible to everyone but the save that staged it: it never touches the store until
/// <see cref="InMemoryDataStore.Publish"/> accepts the whole set at once. "At once" is about the outcome, not about
/// isolation: the staging writes and <see cref="InMemoryDataStore.Publish"/> take the store lock separately, so a
/// reader running in between sees the store as it was before the save. What the staging guarantees is
/// that a save which stops half way - and the phases it runs outside the lock are where it can - never leaves part of
/// itself behind. A save that fails simply drops its staging, which
/// is all the rollback there is - the store was never changed, so there is nothing to undo and nothing another thread's
/// write can be trampled by. That matters because a save hook's After runs outside the store lock: rolling a failed save
/// back by restoring snapshots would silently discard whatever someone else wrote to the same rows while After was running.
/// </para>
/// <para>
/// Alongside the writes, the row each save touched is recorded once, the first time it is touched, together with the
/// snapshot the store held for it at that moment (or nothing at all, when the row did not exist yet). Publishing compares
/// the store against those snapshots to detect a row someone else has written meanwhile.
/// </para>
/// <para>
/// The row version counter is deliberately not rewound when a save is dropped: it only has to keep increasing for a stale
/// version to be distinguishable from a current one, so the versions an abandoned save consumed are simply skipped. The
/// caller entities awaiting a version are recorded here by the row they were written to, not by the version value, so the
/// version that reaches the caller is whichever one is actually published. A save that fails therefore leaves the caller
/// holding the versions it read, and a save hook's After still sees the pre-save version (the same "before commit" view the
/// real backends give).
/// </para>
/// </remarks>
internal sealed class InMemorySaveStaging
{
    private readonly Dictionary<(Type EntityType, object Key), EntityBaseCore?> _overlay = new(
        InMemoryKeyComparer.Instance
    );
    private readonly List<(Type EntityType, object Key, EntityBaseCore? Base)> _baseline = new();
    private readonly Dictionary<(Type EntityType, object Key), bool> _touched = new(InMemoryKeyComparer.Instance);
    private readonly List<(
        EntityBaseCore Source,
        PropertyInfo Property,
        Type EntityType,
        object Key
    )> _stamps = new();

    /// <summary>The rows the save started from, in the order it first touched them (a null base means the row did not exist yet).</summary>
    public IReadOnlyList<(Type EntityType, object Key, EntityBaseCore? Base)> Baseline => _baseline;

    /// <summary>The staged writes (a null value marks a delete).</summary>
    public IReadOnlyDictionary<(Type EntityType, object Key), EntityBaseCore?> Overlay => _overlay;

    /// <summary>The caller entities awaiting the row version of the row they were written to.</summary>
    public IReadOnlyList<(
        EntityBaseCore Source,
        PropertyInfo Property,
        Type EntityType,
        object Key
    )> Stamps => _stamps;

    /// <summary>Records the snapshot the store held for a row when the save first touched it (later touches are ignored).</summary>
    public void CaptureBase(Type entityType, object key, EntityBaseCore? baseRow)
    {
        if (_touched.TryAdd((entityType, key), baseRow is null))
        {
            _baseline.Add((entityType, key, baseRow));
        }
    }

    /// <summary>Whether the row did not exist when the save first touched it (false for a row the save never touched).</summary>
    internal bool StartedWithoutRow(Type entityType, object key) =>
        _touched.TryGetValue((entityType, key), out var absent) && absent;

    /// <summary>Stages a write for a row (a null snapshot marks a delete), replacing whatever the save staged for it before.</summary>
    public void Stage(Type entityType, object key, EntityBaseCore? snapshot) =>
        _overlay[(entityType, key)] = snapshot;

    /// <summary>Gets the write the save has staged for a row (true when it staged one at all, including a delete).</summary>
    public bool TryGetStaged(Type entityType, object key, out EntityBaseCore? snapshot) =>
        _overlay.TryGetValue((entityType, key), out snapshot);

    /// <summary>The snapshot staged for a row (null for a delete as well as for a row the save never staged).</summary>
    public EntityBaseCore? Staged(Type entityType, object key) =>
        _overlay.GetValueOrDefault((entityType, key));

    /// <summary>Records that a caller entity is waiting for the row version the given row ends up published with.</summary>
    public void RecordStamp(
        EntityBaseCore source,
        PropertyInfo property,
        Type entityType,
        object key
    ) => _stamps.Add((source, property, entityType, key));
}

/// <summary>
/// In-memory implementation of <see cref="ISqlQueryExecutor{TEntity}"/>. It evaluates the predicates, orderings, and
/// paging of <see cref="SqlQueryPlan{TEntity}"/> with LINQ-to-Objects, and reconstructs the Include tree's navigations
/// from FK metadata to attach them.
/// </summary>
/// <remarks>
/// Predicates (<see cref="LambdaExpression"/>) are turned into delegates with <see cref="LambdaExpression.Compile()"/> and
/// evaluated directly (no SQL translation). Returned entities are always clones of the store's snapshots, and the
/// navigations attached by Include point to cloned children/parents as well (so caller-side changes do not propagate to the store).
/// </remarks>
internal sealed class InMemoryQueryExecutor<TEntity>(InMemoryDataStore store)
    : ISqlQueryExecutor<TEntity>
    where TEntity : EntityBaseCore, new()
{
    private readonly InMemoryDataStore _store = store;

    /// <summary>Returns the result after applying predicates (AND-combined), orderings, and Skip/Take as Include-attached clones.</summary>
    public Task<IReadOnlyList<TEntity>> ToListAsync(
        SqlQueryPlan<TEntity> plan,
        CancellationToken cancellationToken
    )
    {
        var predicates = CompilePredicates(plan);
        var orderings = CompileOrderings(plan);

        var result = _store.Read(scope =>
        {
            var matched = ApplyOrderingAndPaging(FilterRaw(predicates), plan, orderings);
            // Copy first, then attach Include (so the store's actual entities are not mutated). By default the returned copies leave
            // unbounded binary columns in their not-fetched state (when WithUnboundedBinary is set they are copied as well, so
            // excluded columns are also fetched; the Include-less case is already guarded at the terminal).
            var cloned = matched
                .Select(entity => InMemoryDataStore.CopyRow<TEntity>(entity, plan.WithUnboundedBinary))
                .ToList();

            IncludeAttacher.AttachAll(cloned, plan.Includes, scope);

            return (IReadOnlyList<TEntity>)cloned;
        });

        return Task.FromResult(result);
    }

    /// <summary>Applies the projection to clones after applying predicates, orderings, and Skip/Take, and returns the list (result-equivalent to the real database's column pruning).</summary>
    /// <remarks>
    /// For a selector with no Include and only column references, it projects "from a full clone" (so unbounded binary columns are
    /// also referenceable, giving the same parity as the real database including the referenced columns in the SELECT). When Include
    /// is used or column references cannot be extracted, it projects from the conventional path (a clone with unbounded binary columns
    /// stripped, as in ToListAsync), giving the same parity as the real database's fallback - including <c>WithUnboundedBinary</c>,
    /// which the dialect backends pick up on that path because their fallback goes through ToListAsync.
    /// </remarks>
    public Task<IReadOnlyList<TResult>> ToProjectionListAsync<TResult>(
        SqlQueryPlan<TEntity> plan,
        Expression<Func<TEntity, TResult>> selector,
        CancellationToken cancellationToken
    )
    {
        var project = QuerySelectorCache.GetOrCompile(selector);
        var predicates = CompilePredicates(plan);
        var orderings = CompileOrderings(plan);

        // With no Include and only column references, project from a full clone (excluded columns are also referenceable). Otherwise project from a stripped clone.
        var prunable =
            plan.Includes.Count == 0
            && ProjectionColumnCollector.TryCollect(selector, out var referenced)
            && EntitySaveMetadata.For(typeof(TEntity)).CanPruneProjection(referenced);

        var result = _store.Read(scope =>
        {
            var matched = ApplyOrderingAndPaging(FilterRaw(predicates), plan, orderings);
            var clones = new List<TEntity>(matched.Count);

            foreach (var entity in matched)
            {
                // Always copy before projecting so the projection does not share byte[] and the like with the store's actual entity.
                // Same parity as the conventional path (ToListAsync): unbounded binary columns are left out unless they were asked for
                clones.Add(InMemoryDataStore.CopyRow<TEntity>(entity, prunable || plan.WithUnboundedBinary));
            }

            // ... then attach Include (all clones at once), then project
            if (!prunable)
            {
                IncludeAttacher.AttachAll(clones, plan.Includes, scope);
            }

            var projected = new List<TResult>(clones.Count);
            foreach (var clone in clones)
            {
                projected.Add(project(clone));
            }

            return (IReadOnlyList<TResult>)projected;
        });

        return Task.FromResult(result);
    }

    /// <summary>Returns the first item as an Include-attached clone (null if none).</summary>
    public Task<TEntity?> FirstOrDefaultAsync(
        SqlQueryPlan<TEntity> plan,
        CancellationToken cancellationToken
    )
    {
        var predicates = CompilePredicates(plan);
        var orderings = CompileOrderings(plan);

        var result = _store.Read(scope =>
        {
            var first = ApplyOrderingAndPaging(FilterRaw(predicates), plan, orderings)
                .FirstOrDefault();

            if (first is null)
            {
                return null;
            }

            // By default unbounded binary columns are left in their not-fetched state. When WithUnboundedBinary is set, they are copied as well.
            var cloned = InMemoryDataStore.CopyRow<TEntity>(first, plan.WithUnboundedBinary);

            IncludeAttacher.Attach(cloned, plan.Includes, scope);
            return cloned;
        });

        return Task.FromResult(result);
    }

    /// <summary>Returns the count of rows matching the conditions (orderings, paging, and Include play no part).</summary>
    public Task<int> CountAsync(SqlQueryPlan<TEntity> plan, CancellationToken cancellationToken)
    {
        var predicates = CompilePredicates(plan);
        return Task.FromResult(_store.Read(_ => FilterRaw(predicates).Count()));
    }

    /// <summary>Returns whether any row matches the conditions.</summary>
    public Task<bool> AnyAsync(SqlQueryPlan<TEntity> plan, CancellationToken cancellationToken)
    {
        var predicates = CompilePredicates(plan);
        return Task.FromResult(_store.Read(_ => FilterRaw(predicates).Any()));
    }

    /// <summary>Deletes rows matching the conditions. With cascadeDelete=true, descendants are also deleted along the FK chain.</summary>
    /// <remarks>
    /// A cascade the fixed descendant walk cannot express (a cycle) is rejected before any row is read, whatever the
    /// condition matches, as the SQL backends reject it. The deletes are staged and published as one unit, so a traversal
    /// that fails part-way through leaves the store exactly as it found it: the writes only ever existed in
    /// the staging, so there is nothing to undo. That is abort safety, not isolation - the staging writes and the publish take
    /// the store lock separately, so another thread can still observe the store in between and change the rows this delete
    /// started from, which a database's statement-level rollback would have held locks against. Publishing waives the version
    /// check: a bulk delete states a condition, not the version of any particular row.
    /// </remarks>
    public Task<int> ExecuteDeleteAsync(
        SqlQueryPlan<TEntity> plan,
        bool cascadeDelete,
        CancellationToken cancellationToken
    )
    {
        var predicates = CompilePredicates(plan);

        if (cascadeDelete)
        {
            InMemoryCascade.ThrowIfCascadeIsCyclic(typeof(TEntity));
        }

        var staging = new InMemorySaveStaging();

        var rows = _store.Write(
            scope =>
            {
                // Determine the delete targets by the primary keys of the snapshots (pre-clone) as evaluated at this point.
                var targets = FilterRaw(predicates).ToList();
                var removed = 0;

                foreach (var target in targets)
                {
                    if (cascadeDelete)
                    {
                        removed += InMemoryCascade.DeleteDescendants(target, scope);
                    }

                    if (scope.Remove(typeof(TEntity), InMemoryDataStore.KeyOf(target)))
                    {
                        removed++;
                    }
                }

                return removed;
            },
            staging
        );

        _store.Publish(staging, ConcurrencyMode.ForceOverwrite);
        return Task.FromResult(rows);
    }

    /// <summary>Compiles the plan's predicates into delegates.</summary>
    /// <remarks>
    /// Compiling an expression tree is expensive, and it is done before the store lock is taken on purpose: doing it inside
    /// would serialize every read in the process behind one query's compilation. A navigation property is rejected first
    /// (see <see cref="NavigationGuard"/>), and equality and <c>Contains</c> over <c>byte[]</c> are rewritten to a byte-wise
    /// comparison (see <see cref="ByteArrayEqualityRewriter"/>).
    /// </remarks>
    private static Func<TEntity, bool>[] CompilePredicates(SqlQueryPlan<TEntity> plan) =>
        plan.Predicates.Select(predicate =>
            {
                NavigationGuard.Instance.Visit(predicate);
                return (Func<TEntity, bool>)
                    ((LambdaExpression)ByteArrayEqualityRewriter.Instance.Visit(predicate)).Compile();
            })
            .ToArray();

    /// <summary>Compares two byte arrays by value (two nulls are equal; one null never matches).</summary>
    /// <remarks>
    /// Same semantics as the binary value object's equality: the SQL backends compare the column's actual bytes,
    /// so a null against a value never matches and two equal blobs always do.
    /// </remarks>
    private static bool AreBytesEqual(byte[]? left, byte[]? right) =>
        left is null ? right is null : right is not null && left.AsSpan().SequenceEqual(right);

    /// <summary>The <see cref="AreBytesEqual"/> method, resolved once for the rewriter.</summary>
    private static readonly MethodInfo AreBytesEqualMethod = typeof(InMemoryQueryExecutor<TEntity>).GetMethod(
        nameof(AreBytesEqual),
        BindingFlags.NonPublic | BindingFlags.Static
    )!;

    /// <summary>Whether a collection of byte arrays holds one with the same bytes as <paramref name="value"/> (an IN over a binary column).</summary>
    private static bool ContainsBytes(IEnumerable<byte[]?> source, byte[]? value)
    {
        foreach (var item in source)
        {
            if (AreBytesEqual(item, value))
            {
                return true;
            }
        }

        return false;
    }

    /// <summary>The <see cref="ContainsBytes"/> method, resolved once for the rewriter.</summary>
    private static readonly MethodInfo ContainsBytesMethod = typeof(InMemoryQueryExecutor<TEntity>).GetMethod(
        nameof(ContainsBytes),
        BindingFlags.NonPublic | BindingFlags.Static
    )!;

    /// <summary>
    /// Rewrites <c>==</c> / <c>!=</c> over <c>byte[]</c> operands, and a <c>Contains</c> over a collection of <c>byte[]</c>
    /// (an IN), into a byte-wise comparison before the predicate is compiled.
    /// </summary>
    /// <remarks>
    /// C#'s <c>==</c> on arrays is reference equality, and so is the default comparer a collection's <c>Contains</c> uses,
    /// so a compiled predicate would treat two equal blobs as different - the SQL backends compare the column's actual
    /// bytes, and the in-memory store hands out cloned arrays by design, which makes reference equality never match.
    /// Value-object columns are unaffected (their operators already compare by value), and other operand types keep their
    /// C# semantics untouched.
    /// </remarks>
    private sealed class ByteArrayEqualityRewriter : ExpressionVisitor
    {
        /// <summary>The shared stateless instance.</summary>
        public static readonly ByteArrayEqualityRewriter Instance = new();

        /// <inheritdoc />
        protected override Expression VisitBinary(BinaryExpression node)
        {
            if (
                node.NodeType is ExpressionType.Equal or ExpressionType.NotEqual
                && node.Left.Type == typeof(byte[])
                && node.Right.Type == typeof(byte[])
            )
            {
                var call = Expression.Call(AreBytesEqualMethod, Visit(node.Left), Visit(node.Right));
                return node.NodeType == ExpressionType.Equal
                    ? call
                    : Expression.Not(call);
            }

            return base.VisitBinary(node);
        }

        /// <inheritdoc />
        protected override Expression VisitMethodCall(MethodCallExpression node)
        {
            // Enumerable.Contains(source, value), or an instance Contains(value) on a List / HashSet / ICollection
            if (node.Method.Name == nameof(Enumerable.Contains))
            {
                var source = node.Object ?? (node.Arguments.Count == 2 ? node.Arguments[0] : null);
                var value = node.Object is null
                    ? (node.Arguments.Count == 2 ? node.Arguments[1] : null)
                    : (node.Arguments.Count == 1 ? node.Arguments[0] : null);

                if (
                    source is not null
                    && value is not null
                    && value.Type == typeof(byte[])
                    && typeof(IEnumerable<byte[]>).IsAssignableFrom(source.Type)
                )
                {
                    return Expression.Call(
                        ContainsBytesMethod,
                        Expression.Convert(Visit(source), typeof(IEnumerable<byte[]?>)),
                        Visit(value)
                    );
                }
            }

            return base.VisitMethodCall(node);
        }
    }

    /// <summary>Rejects a navigation property in a query condition or ordering, as the SQL backends do.</summary>
    /// <remarks>
    /// A navigation is not a column. The SQL backends refuse to translate one, and here the store holds rows rather than
    /// graphs, so a navigation read off a stored row is always empty: <c>x.Orders.Any()</c> would match no row and
    /// <c>x.Customer == null</c> every row, without an error. Only a navigation reached from the entity being queried is
    /// rejected; a value captured from outside the query is evaluated like any other value.
    /// </remarks>
    private sealed class NavigationGuard : ExpressionVisitor
    {
        /// <summary>The shared stateless instance.</summary>
        public static readonly NavigationGuard Instance = new();

        /// <inheritdoc />
        protected override Expression VisitMember(MemberExpression node)
        {
            if (
                node.Member is PropertyInfo property
                && EntitySaveMetadata.NavigationAttribute(property) is not null
                && IsReadOffParameter(node.Expression)
            )
            {
                throw new NotSupportedException(
                    $"'{property.DeclaringType?.Name}.{property.Name}' is a navigation property and cannot be used in a query condition or ordering; "
                        + "filter on the foreign-key column instead."
                );
            }

            return base.VisitMember(node);
        }

        /// <summary>Whether the expression is a lambda parameter, possibly through member accesses and conversions.</summary>
        private static bool IsReadOffParameter(Expression? expression)
        {
            while (true)
            {
                switch (expression)
                {
                    case ParameterExpression:
                        return true;
                    case MemberExpression member:
                        expression = member.Expression;
                        break;
                    case UnaryExpression
                    {
                        NodeType: ExpressionType.Convert
                            or ExpressionType.ConvertChecked
                            or ExpressionType.TypeAs
                    } unary:
                        expression = unary.Operand;
                        break;
                    default:
                        return false;
                }
            }
        }
    }

    /// <summary>Compiles the plan's ordering key selectors into delegates (paired with their direction). Called outside the store lock, for the same reason as <see cref="CompilePredicates"/>.</summary>
    private static (Func<TEntity, object?> KeySelector, bool Descending)[] CompileOrderings(
        SqlQueryPlan<TEntity> plan
    ) =>
        plan
            .Orderings.Select(ordering =>
            {
                NavigationGuard.Instance.Visit(ordering.KeySelector);
                return ((Func<TEntity, object?>)ordering.KeySelector.Compile(), ordering.Descending);
            })
            .ToArray();

    /// <summary>Filters the store's raw snapshots by applying the predicates (AND-combined) (pre-clone, enumeration only).</summary>
    private IEnumerable<EntityBaseCore> FilterRaw(Func<TEntity, bool>[] predicates)
    {
        IEnumerable<TEntity> query = _store.RawSnapshotUnlocked(typeof(TEntity)).Cast<TEntity>();

        foreach (var predicate in predicates)
        {
            query = query.Where(predicate);
        }

        return query;
    }

    /// <summary>Applies the orderings (stable sort in the specified order) and Skip/Take.</summary>
    private static IReadOnlyList<EntityBaseCore> ApplyOrderingAndPaging(
        IEnumerable<EntityBaseCore> source,
        SqlQueryPlan<TEntity> plan,
        (Func<TEntity, object?> KeySelector, bool Descending)[] orderings
    )
    {
        var typed = source.Cast<TEntity>();
        IOrderedEnumerable<TEntity>? ordered = null;

        foreach (var ordering in orderings)
        {
            var keySelector = ordering.KeySelector;

            if (ordered is null)
            {
                ordered = ordering.Descending
                    ? typed.OrderByDescending(keySelector, InMemoryOrderingComparer.Instance)
                    : typed.OrderBy(keySelector, InMemoryOrderingComparer.Instance);
            }
            else
            {
                ordered = ordering.Descending
                    ? ordered.ThenByDescending(keySelector, InMemoryOrderingComparer.Instance)
                    : ordered.ThenBy(keySelector, InMemoryOrderingComparer.Instance);
            }
        }

        IEnumerable<TEntity> result = ordered ?? typed;

        if (plan.Skip is { } skip)
        {
            result = result.Skip(skip);
        }

        if (plan.Take is { } take)
        {
            result = result.Take(take);
        }

        return result.Cast<EntityBaseCore>().ToList();
    }
}

/// <summary>Compares the keys an ORDER BY sorts on, following the database's ordering rather than the CLR's default one.</summary>
/// <remarks>
/// <para>
/// Two of the CLR defaults diverge from a database. Binary values do not implement <see cref="IComparable"/> at all, so
/// <see cref="Comparer{T}.Default"/> throws on them, whereas ordering by a binary column is perfectly ordinary in SQL; they
/// are compared byte by byte here, which is the order SQL Server gives <c>varbinary</c>. Strings compare culture-sensitively
/// by default, while every other string comparison in this backend is ordinal, so ordering is ordinal too (a real database
/// orders by its collation, which this backend does not model - see the divergences the documentation lists at
/// https://github.com/kokko-labs/QuickER/blob/main/docs/code-generation.md).
/// </para>
/// <para>
/// Null sorts before everything else, which an ascending <c>ORDER BY</c> does as well (and descending duly puts it last).
/// </para>
/// </remarks>
internal sealed class InMemoryOrderingComparer : IComparer<object?>
{
    /// <summary>The shared instance (the comparer holds no state).</summary>
    public static readonly InMemoryOrderingComparer Instance = new();

    private InMemoryOrderingComparer() { }

    /// <summary>Compares two ordering keys.</summary>
    public int Compare(object? x, object? y)
    {
        // Value objects are opened first, so a wrapped value orders by the value it wraps
        x = SqlParameterValue.Unwrap(x);
        y = SqlParameterValue.Unwrap(y);

        if (x is null || y is null)
        {
            return x is null ? (y is null ? 0 : -1) : 1;
        }

        if (x is byte[] left && y is byte[] right)
        {
            return left.AsSpan().SequenceCompareTo(right);
        }

        if (x is string first && y is string second)
        {
            return string.CompareOrdinal(first, second);
        }

        return Comparer<object>.Default.Compare(x, y);
    }
}

/// <summary>Reconstructs navigations (child collections, parent references) from FK metadata along the Include tree and attaches them to the cloned graph.</summary>
/// <remarks>
/// The navigations of a whole result are attached together: for each Include node the related table is read once and indexed
/// by the key it is matched on, instead of being scanned again for every entity. Keys are matched in the form
/// <see cref="IncludeKeys"/> gives them, so a principal key and a foreign key of different CLR types (a long key referred to by
/// an int column) still meet. Every entity gets clones of its own; the store's snapshots are never handed out.
/// </remarks>
internal static class IncludeAttacher
{
    /// <summary>Recursively attaches the navigations for the Include tree onto the given (cloned) entity.</summary>
    public static void Attach(
        EntityBaseCore entity,
        IReadOnlyList<IncludeNode> includes,
        InMemoryDataStore.InMemoryReadScope scope
    ) => AttachAll(new[] { entity }, includes, scope);

    /// <summary>Recursively attaches the navigations for the Include tree onto every given (cloned) entity of one type.</summary>
    public static void AttachAll(
        IReadOnlyList<EntityBaseCore> entities,
        IReadOnlyList<IncludeNode> includes,
        InMemoryDataStore.InMemoryReadScope scope
    )
    {
        if (entities.Count == 0 || includes.Count == 0)
        {
            return;
        }

        foreach (var node in includes)
        {
            var attribute =
                EntitySaveMetadata.NavigationAttribute(node.Property)
                ?? throw new InvalidOperationException(
                    $"{node.Property.Name} is not a navigation that has [NavigationReference]."
                );

            var metadata = EntitySaveMetadata.For(entities[0].GetType());

            if (attribute.IsCollection || !attribute.IsParentReference)
            {
                AttachChildren(entities, node, attribute, metadata, scope);
            }
            else
            {
                AttachParents(entities, node, attribute, metadata, scope);
            }
        }
    }

    /// <summary>Fills a collection or child-direction single-reference navigation with the children whose FK matches each parent's key.</summary>
    private static void AttachChildren(
        IReadOnlyList<EntityBaseCore> parents,
        IncludeNode node,
        NavigationReferenceAttribute attribute,
        EntitySaveMetadata parentMetadata,
        InMemoryDataStore.InMemoryReadScope scope
    )
    {
        var childType = attribute.IsCollection
            ? node.Property.PropertyType.GetGenericArguments()[0]
            : node.Property.PropertyType;
        var childMetadata = EntitySaveMetadata.For(childType);

        // One pass over the child table, grouped by the (normalized) foreign key
        var childrenByKey = new Dictionary<object, List<EntityBaseCore>>();
        foreach (var child in scope.All(childType))
        {
            if (ColumnValue(child, attribute.DependentColumn, childMetadata) is not { } fk)
            {
                continue;
            }

            if (!childrenByKey.TryGetValue(fk, out var bucket))
            {
                bucket = new List<EntityBaseCore>();
                childrenByKey[fk] = bucket;
            }

            bucket.Add(child);
        }

        var attached = new List<EntityBaseCore>();
        foreach (var parent in parents)
        {
            var matched = new List<EntityBaseCore>();

            if (
                ColumnValue(parent, attribute.PrincipalColumn, parentMetadata) is { } parentKey
                && childrenByKey.TryGetValue(parentKey, out var bucket)
            )
            {
                foreach (var child in bucket)
                {
                    matched.Add(InMemoryDataStore.CopyRow<EntityBaseCore>(child));
                }
            }

            attached.AddRange(matched);

            if (attribute.IsCollection)
            {
                // Create a concrete List for ICollection<childType> and fill it.
                var listType = typeof(List<>).MakeGenericType(childType);
                var list = (System.Collections.IList)Activator.CreateInstance(listType)!;

                foreach (var child in matched)
                {
                    list.Add(child);
                }

                node.Property.SetValue(parent, list);
            }
            else
            {
                node.Property.SetValue(parent, matched.Count > 0 ? matched[0] : null);
            }
        }

        AttachAll(attached, node.Children, scope);
    }

    /// <summary>Fills a parent-reference navigation with the parent that each entity's own FK points to.</summary>
    private static void AttachParents(
        IReadOnlyList<EntityBaseCore> dependents,
        IncludeNode node,
        NavigationReferenceAttribute attribute,
        EntitySaveMetadata dependentMetadata,
        InMemoryDataStore.InMemoryReadScope scope
    )
    {
        var parentType = node.Property.PropertyType;
        var parentMetadata = EntitySaveMetadata.For(parentType);

        // One pass over the parent table, indexed by the (normalized) principal key; the first row wins, as the scan did
        var parentsByKey = new Dictionary<object, EntityBaseCore>();
        foreach (var candidate in scope.All(parentType))
        {
            if (ColumnValue(candidate, attribute.PrincipalColumn, parentMetadata) is { } principal)
            {
                parentsByKey.TryAdd(principal, candidate);
            }
        }

        var attached = new List<EntityBaseCore>();
        foreach (var dependent in dependents)
        {
            if (
                ColumnValue(dependent, attribute.DependentColumn, dependentMetadata) is { } fk
                && parentsByKey.TryGetValue(fk, out var parent)
            )
            {
                var clonedParent = InMemoryDataStore.CopyRow<EntityBaseCore>(parent);
                node.Property.SetValue(dependent, clonedParent);
                attached.Add(clonedParent);
            }
            else
            {
                node.Property.SetValue(dependent, null);
            }
        }

        AttachAll(attached, node.Children, scope);
    }

    /// <summary>Reads the value of the given column from an entity in the form keys are matched in (<see cref="IncludeKeys"/>).</summary>
    private static object? ColumnValue(
        EntityBaseCore entity,
        string columnName,
        EntitySaveMetadata metadata
    )
    {
        if (!metadata.PropertyByColumn.TryGetValue(columnName, out var property))
        {
            throw new InvalidOperationException(
                $"{entity.GetType().Name} has no property corresponding to column {columnName}."
            );
        }

        return IncludeKeys.Normalize(property.GetValue(entity));
    }
}

/// <summary>Cascade save/delete for the in-memory repository (traversing child navigations derived from FK metadata).</summary>
/// <remarks>
/// A loaded graph is walked through <see cref="EntityBaseCore.EnumerateCascadeChildren"/>, the cascade traversal every graph
/// operation shares; only <see cref="DeleteDescendants"/>, which has no loaded graph, reads the cascade navigations of the
/// metadata to find the child rows in the store.
/// </remarks>
internal static class InMemoryCascade
{
    /// <summary>Saves the graph driven by RowState and returns the number of rows written (same semantics as QuickER's EntityGraphSaver).</summary>
    /// <remarks>
    /// IsRemoved deletes children first and then the entity itself, IsAdded inserts, and IsUpdated updates (when the target is
    /// missing, insertWhenUpdateMissing either inserts or throws a conflict exception). Inserts/updates process the entity itself
    /// first; deletes process the children first. When <paramref name="hooks"/> is provided, Put/Remove is suppressed for nodes
    /// contained in <see cref="SaveHookSession.Skipped"/>, and the operations actually performed are recorded into
    /// <paramref name="records"/> (in execution order), which is used to determine the After firing order and the actual operations.
    /// Entities whose type has a rowversion column are guarded by <paramref name="mode"/>: updating or deleting a row that
    /// someone else changed first is rejected. A conflict found part-way through does not leave the earlier writes behind:
    /// when the caller gave the write scope a staging, none of them ever reached the store to begin with.
    /// </remarks>
    public static int Save(
        EntityBaseCore entity,
        InMemoryDataStore.InMemoryWriteScope scope,
        bool cascadeSave,
        bool cascadeDelete,
        bool insertWhenUpdateMissing,
        ConcurrencyMode mode,
        SaveHookSession? hooks = null,
        List<(EntityBaseCore Entity, SaveOperation Operation)>? records = null,
        bool changesAlreadyVerified = false
    )
    {
        // If the caller already verified HasChanges, skip the redundant graph traversal here (recursion into children keeps the default false so each branch is checked).
        if (!changesAlreadyVerified && !EntityGraphSaver.HasChanges(entity, cascadeSave))
        {
            return 0;
        }

        var rows = 0;
        var entityType = entity.GetType();
        var key = InMemoryDataStore.KeyOf(entity);

        if (entity.IsRemoved)
        {
            if (cascadeDelete)
            {
                foreach (var child in entity.EnumerateCascadeChildren())
                {
                    rows += DeleteGraph(child, scope, mode, hooks, records);
                }
            }

            // If Before(Delete) returned false (skip), only the entity's own deletion is withheld (children were already deleted above, so the entity itself remains).
            if (hooks is not null && hooks.Skipped.Contains(entity))
            {
                return rows;
            }

            // A row someone else changed first must not be deleted (a row that is simply gone stays tolerated silently).
            if (!scope.IsCurrent(entity, mode))
            {
                throw SaveConflictException.Modified(entityType, key, "delete");
            }

            if (scope.Remove(entityType, key))
            {
                rows++;
            }

            records?.Add((entity, SaveOperation.Delete));
            return rows;
        }

        if (entity.IsAdded)
        {
            // Insert unless skipped (even when skipped, the child cascade continues).
            if (hooks is null || !hooks.Skipped.Contains(entity))
            {
                scope.Insert(entity);
                rows++;
                records?.Add((entity, SaveOperation.Insert));
            }
        }
        else if (entity.IsUpdated)
        {
            if (hooks is null || !hooks.Skipped.Contains(entity))
            {
                // As with graph updates against a real database, reject updates that still carry values in unbounded binary columns.
                UnboundedBinaryColumns.ThrowIfExcludedAssigned(entity);

                if (scope.Exists(entityType, key))
                {
                    // A row someone else changed first must not be overwritten, and must never be switched to an INSERT
                    // below (which would turn a stale version into a duplicate primary key).
                    if (!scope.IsCurrent(entity, mode))
                    {
                        throw SaveConflictException.Modified(entityType, key, "update");
                    }

                    scope.Put(entity);
                    rows++;
                    records?.Add((entity, SaveOperation.Update));
                }
                else if (insertWhenUpdateMissing)
                {
                    // The update target was missing and the operation switched to INSERT, so After fires with the actual operation Insert.
                    scope.Insert(entity);
                    rows++;
                    records?.Add((entity, SaveOperation.Insert));
                }
                else
                {
                    throw SaveConflictException.NotFound(entityType, key);
                }
            }
        }

        if (cascadeSave)
        {
            foreach (var child in entity.EnumerateCascadeChildren())
            {
                rows += Save(
                    child,
                    scope,
                    cascadeSave,
                    cascadeDelete,
                    insertWhenUpdateMissing,
                    mode,
                    hooks,
                    records
                );
            }
        }

        return rows;
    }

    /// <summary>Phase 1: traverses the graph in the same order as <see cref="Save"/>, fires the pre-operation hooks (Before), and builds the skip set (outside the lock, async).</summary>
    /// <remarks>Before fires with the RowState-derived operation (even when <c>insertWhenUpdateMissing</c> switches to Insert, it fires once as Update). The actual operation is determined by the save phase.</remarks>
    public static async Task InvokeBeforeGraphAsync(
        EntityBaseCore entity,
        SaveHookSession hooks,
        bool cascadeSave,
        bool cascadeDelete,
        CancellationToken cancellationToken,
        bool changesAlreadyVerified = false
    )
    {
        // If the caller already verified HasChanges, skip the redundant graph traversal here (recursion into children keeps the default false so each branch is checked).
        if (!changesAlreadyVerified && !EntityGraphSaver.HasChanges(entity, cascadeSave))
        {
            return;
        }

        if (entity.IsRemoved)
        {
            // For deletes, fire Before starting from the children (same order as Save / DeleteGraph).
            if (cascadeDelete)
            {
                foreach (var child in entity.EnumerateCascadeChildren())
                {
                    await InvokeBeforeDeleteGraphAsync(child, hooks, cancellationToken).ConfigureAwait(false);
                }
            }

            if (!await hooks.InvokeBeforeAsync(entity, SaveOperation.Delete, cancellationToken).ConfigureAwait(false))
            {
                hooks.Skip(entity);
            }

            return;
        }

        if (entity.IsAdded)
        {
            if (!await hooks.InvokeBeforeAsync(entity, SaveOperation.Insert, cancellationToken).ConfigureAwait(false))
            {
                hooks.Skip(entity);
            }
        }
        else if (entity.IsUpdated)
        {
            if (!await hooks.InvokeBeforeAsync(entity, SaveOperation.Update, cancellationToken).ConfigureAwait(false))
            {
                hooks.Skip(entity);
            }
        }

        if (cascadeSave)
        {
            foreach (var child in entity.EnumerateCascadeChildren())
            {
                await InvokeBeforeGraphAsync(
                    child,
                    hooks,
                    cascadeSave,
                    cascadeDelete,
                    cancellationToken
                ).ConfigureAwait(false);
            }
        }
    }

    /// <summary>Fires Before for a subtree delete starting from the children (same order as <see cref="DeleteGraph"/>).</summary>
    private static async Task InvokeBeforeDeleteGraphAsync(
        EntityBaseCore entity,
        SaveHookSession hooks,
        CancellationToken cancellationToken
    )
    {
        foreach (var child in entity.EnumerateCascadeChildren())
        {
            await InvokeBeforeDeleteGraphAsync(child, hooks, cancellationToken).ConfigureAwait(false);
        }

        if (!await hooks.InvokeBeforeAsync(entity, SaveOperation.Delete, cancellationToken).ConfigureAwait(false))
        {
            hooks.Skip(entity);
        }
    }

    /// <summary>Deletes a subtree starting from the children (deletes regardless of state; when <paramref name="hooks"/> is provided, skipped rows are left in place and the deletes actually performed are recorded into <paramref name="records"/>).</summary>
    private static int DeleteGraph(
        EntityBaseCore entity,
        InMemoryDataStore.InMemoryWriteScope scope,
        ConcurrencyMode mode,
        SaveHookSession? hooks = null,
        List<(EntityBaseCore Entity, SaveOperation Operation)>? records = null
    )
    {
        var rows = 0;

        foreach (var child in entity.EnumerateCascadeChildren())
        {
            rows += DeleteGraph(child, scope, mode, hooks, records);
        }

        // If Before(Delete) returned false (skip), do not delete the entity itself (children are already deleted).
        if (hooks is not null && hooks.Skipped.Contains(entity))
        {
            return rows;
        }

        var key = InMemoryDataStore.KeyOf(entity);

        // A row someone else changed first must not be deleted (a row that is simply gone stays tolerated silently).
        if (!scope.IsCurrent(entity, mode))
        {
            throw SaveConflictException.Modified(entity.GetType(), key, "delete");
        }

        if (scope.Remove(entity.GetType(), key))
        {
            rows++;
        }

        records?.Add((entity, SaveOperation.Delete));
        return rows;
    }

    /// <summary>For ExecuteDelete, which has no loaded graph, deletes descendants in the store along the FK chain (grandchildren before children).</summary>
    /// <remarks>
    /// Follows the cascade navigations (FK metadata) and finds and deletes children in the store whose DependentColumn matches the
    /// parent's PrincipalColumn value. Cyclic cascades (self-references and the like) cannot be expressed by this fixed traversal;
    /// the caller rejects them up front with <see cref="ThrowIfCascadeIsCyclic"/>, so the traversal here always terminates.
    /// </remarks>
    public static int DeleteDescendants(
        EntityBaseCore parent,
        InMemoryDataStore.InMemoryWriteScope scope
    )
    {
        var rows = 0;
        var parentMetadata = EntitySaveMetadata.For(parent.GetType());

        foreach (var navigation in parentMetadata.CascadeNavigations)
        {
            var childMetadata = EntitySaveMetadata.For(navigation.ChildType);
            var parentKey = ColumnValue(parent, navigation.PrincipalColumn, parentMetadata);

            // Materialize the child snapshots first so the enumeration is not broken while deleting.
            var children = scope
                .All(navigation.ChildType)
                .Where(child =>
                    parentKey is not null
                    && Equals(
                        ColumnValue(child, navigation.DependentColumn, childMetadata),
                        parentKey
                    )
                )
                .ToList();

            foreach (var child in children)
            {
                // Delete grandchildren and below first, then the child (FK consistency).
                rows += DeleteDescendants(child, scope);

                if (scope.Remove(navigation.ChildType, InMemoryDataStore.KeyOf(child)))
                {
                    rows++;
                }
            }
        }

        return rows;
    }

    /// <summary>Caches, per root type, the child type that closes a cascade cycle (<c>null</c> when the cascade is acyclic).</summary>
    private static readonly ConcurrentDictionary<Type, Type?> _cyclicCascadeCache = new();

    /// <summary>Throws when the cascade reachable from <paramref name="rootType"/> contains a cycle, which a cascading ExecuteDelete cannot express.</summary>
    /// <remarks>
    /// The verdict comes from the metadata alone, before any row is read, so it does not depend on how many rows the
    /// condition matches: a delete that happens to match nothing is rejected all the same, as the SQL backends' cascade
    /// planners reject the shape before running anything.
    /// </remarks>
    public static void ThrowIfCascadeIsCyclic(Type rootType)
    {
        var childType = _cyclicCascadeCache.GetOrAdd(
            rootType,
            static type => FindCyclicChild(type, new HashSet<Type> { type })
        );

        if (childType is not null)
        {
            throw new NotSupportedException(
                $"A cyclic cascade ({childType.Name}) is not supported by ExecuteDeleteAsync. Load the graph and use SaveAsync, or use SaveAsync against an already loaded graph."
            );
        }
    }

    /// <summary>Walks the cascade navigations depth first and returns the child type met twice on one path (<c>null</c> when there is none).</summary>
    private static Type? FindCyclicChild(Type parentType, HashSet<Type> path)
    {
        foreach (var navigation in EntitySaveMetadata.For(parentType).CascadeNavigations)
        {
            if (!path.Add(navigation.ChildType))
            {
                return navigation.ChildType;
            }

            var found = FindCyclicChild(navigation.ChildType, path);
            path.Remove(navigation.ChildType);

            if (found is not null)
            {
                return found;
            }
        }

        return null;
    }

    /// <summary>Reads the value of the given column from an entity in the form keys are matched in (<see cref="IncludeKeys"/>).</summary>
    private static object? ColumnValue(
        EntityBaseCore entity,
        string columnName,
        EntitySaveMetadata metadata
    )
    {
        if (!metadata.PropertyByColumn.TryGetValue(columnName, out var property))
        {
            throw new InvalidOperationException(
                $"{entity.GetType().Name} has no property corresponding to column {columnName}."
            );
        }

        // Matched in the same form as the Include attacher (a long principal key and an int foreign key still meet)
        return IncludeKeys.Normalize(property.GetValue(entity));
    }
}

/// <summary>Base class for in-memory repositories implementing CRUD over the in-memory data store (dialect-independent, no real database required).</summary>
/// <remarks>
/// <para>
/// Read operations (GetById/GetAll/Query) always return clones of the store's snapshots with RowState=Unchanged
/// (mutating a returned entity leaves the store unchanged). Write operations (Insert/Update/Delete/Save) replace the snapshots.
/// Raw SQL operations (QueryBySql/ExecuteSql/ExecuteScalarSql) cannot run in memory and throw <see cref="NotSupportedException"/>.
/// </para>
/// </remarks>
public abstract class InMemoryRepositoryCore<TEntity, TKey>(
    InMemoryDataStore store,
    ISaveHookRegistry? saveHooks = null
) : IRepositoryCore<TEntity, TKey>
    where TEntity : EntityBaseCore, new()
{
    /// <summary>The data store holding the snapshots (shared via DI).</summary>
    protected InMemoryDataStore Store { get; } = store;

    /// <summary>The save hook registry (unspecified = null = no hooks, a complete no-op).</summary>
    private readonly ISaveHookRegistry? _saveHooks = saveHooks;

    private const string RawSqlNotSupported =
        "The in-memory repository cannot execute raw SQL. Switch to a real database repository.";

    /// <summary>Gets a single entity by primary key (null if not found).</summary>
    public Task<TEntity?> GetByIdAsync(TKey id, CancellationToken cancellationToken = default) =>
        Task.FromResult(Store.Find<TEntity>(NormalizeKey(id)));

    /// <summary>Gets all entities.</summary>
    public Task<IReadOnlyList<TEntity>> GetAllAsync(CancellationToken cancellationToken = default) =>
        Task.FromResult(Store.Snapshot<TEntity>());

    /// <summary>Inserts an entity (an existing primary key, or a value another row already holds on a UNIQUE constraint, is rejected as a real database would).</summary>
    /// <remarks>
    /// Like every other backend, the direct CRUD operations leave the argument's <c>RowState</c> alone: settling it is
    /// what <c>SaveAsync</c> does after a successful graph save. Doing it here as well would make an entity marked
    /// Added silently turn into a no-op on a following save, where a real database reports the duplicate key.
    /// </remarks>
    public Task InsertAsync(TEntity entity, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(entity);
        Store.Insert(entity);
        return Task.CompletedTask;
    }

    /// <summary>Bulk-inserts a collection of entities.</summary>
    /// <remarks>
    /// Unlike the other backends, the whole batch is checked for duplicate primary keys and for the declared UNIQUE
    /// constraints (against the store and within the batch itself) before any of it is applied, so a duplicate rejects the
    /// batch without leaving part of it inserted - which is what a real database's single transaction gives.
    /// </remarks>
    public Task<int> BulkInsertAsync(
        IEnumerable<TEntity> entities,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entities);
        cancellationToken.ThrowIfCancellationRequested();

        // A collection known to be empty is answered without touching the store
        if (entities is ICollection<TEntity> { Count: 0 })
        {
            return Task.FromResult(0);
        }

        var targets = entities.Where(entity => entity is not null).ToList();

        var count = Store.Write(scope =>
        {
            var batchKeys = new HashSet<object>(InMemoryKeyComparer.Instance);

            // The store's rows are indexed once per type and each accepted row joins the index, so the whole batch is checked
            // against the store and against its own preceding rows without comparing every pair
            var indexes = new Dictionary<Type, InMemoryUniqueness.Index?>();

            // Pre-validate all keys and constraint values, then apply: a duplicate must not leave a partially inserted batch behind.
            foreach (var entity in targets)
            {
                var entityType = entity.GetType();
                var key = InMemoryDataStore.KeyOf(entity);

                if (scope.Exists(entityType, key) || !batchKeys.Add(key))
                {
                    throw InMemoryDataStore.DuplicateKeyError(entityType, key);
                }

                if (!indexes.TryGetValue(entityType, out var index))
                {
                    index = scope.UniquenessIndex(entityType);
                    indexes.Add(entityType, index);
                }

                index?.Verify(key, entity);
                index?.Add(key, entity);
            }

            foreach (var entity in targets)
            {
                scope.Insert(entity);
            }

            return targets.Count;
        });

        return Task.FromResult(count);
    }

    /// <summary>Updates an entity (true if the update target existed).</summary>
    /// <remarks>
    /// When the type has a rowversion column, <paramref name="mode"/> decides whether the update is guarded by the version
    /// the entity was read with. A guarded update against a row someone else changed first throws a
    /// <see cref="SaveConflictException"/>; a row that no longer exists still returns <c>false</c>. On success the entity
    /// receives the newly assigned version. A value another row already holds on a declared UNIQUE constraint is rejected
    /// before the write, as a real database's constraint would reject the statement.
    /// </remarks>
    /// <param name="entity">The entity to update.</param>
    /// <param name="mode">How a concurrent modification is handled when the type has a rowversion column (no effect otherwise). An undefined value throws <see cref="ArgumentOutOfRangeException"/>.</param>
    /// <param name="cancellationToken">The cancellation token.</param>
    public Task<bool> UpdateAsync(
        TEntity entity,
        ConcurrencyMode mode = ConcurrencyMode.Optimistic,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entity);
        mode = ConcurrencyModes.Validated(mode);

        // As with a real database, reject updates that still carry values in unbounded binary columns (checked here individually because this path does not go through BindUpdateParameters).
        UnboundedBinaryColumns.ThrowIfExcludedAssigned(entity);

        var updated = Store.Write(scope =>
        {
            var key = InMemoryDataStore.KeyOf(entity);

            if (!scope.Exists(typeof(TEntity), key))
            {
                return false;
            }

            // A row that is gone keeps the pre-existing "false" contract; a row someone else changed first is a conflict
            if (!scope.IsCurrent(entity, mode))
            {
                throw SaveConflictException.Modified(typeof(TEntity), key, "update");
            }

            // Rejected before the write, as a real database's UNIQUE constraint would reject the statement
            scope.VerifyUnique(entity, key);
            scope.Put(entity);
            return true;
        });

        return Task.FromResult(updated);
    }

    /// <inheritdoc />
    public Task<bool> DeleteAsync(TKey id, CancellationToken cancellationToken = default) =>
        Task.FromResult(Store.Remove(typeof(TEntity), NormalizeKey(id)));

    /// <summary>Starts a query that fetches entities with chained filter conditions, orderings, and Includes.</summary>
    public SqlQuery<TEntity> Query() => new(new InMemoryQueryExecutor<TEntity>(Store));

    /// <summary>Gets the UNIQUE constraints the pre-check walks (the generated repository overrides this with its own table; empty here).</summary>
    protected virtual UniquenessConstraintSet<TEntity> UniquenessConstraints =>
        UniquenessConstraintSet<TEntity>.Empty;

    /// <summary>Collects the user-defined uniqueness checks (the generated repository overrides this to reach its own partial hook).</summary>
    /// <param name="checks">The list to add the checks to (null until the first one is added).</param>
    protected virtual void CollectUniquenessChecks(ref List<UniquenessCheck<TEntity>>? checks) { }

    /// <inheritdoc />
    public async Task<IReadOnlyList<UniquenessViolation>> CheckUniquenessAsync(
        TEntity entity,
        CancellationToken cancellationToken = default
    )
    {
        var constraints = UniquenessConstraints;
        var violations = await UniquenessChecker
            .CheckAsync(
                entity,
                Query,
                constraints.ExcludeSelf,
                constraints.Constraints,
                cancellationToken
            )
            .ConfigureAwait(false);

        List<UniquenessCheck<TEntity>>? customChecks = null;
        CollectUniquenessChecks(ref customChecks);
        await UniquenessChecker
            .RunCustomChecksAsync(entity, customChecks, violations, cancellationToken)
            .ConfigureAwait(false);

        return violations;
    }

    /// <summary>
    /// Reads an unbounded binary column (excluded column) by primary key into the destination stream (in-memory parity
    /// with the real database's streaming). Writes out the store's raw value (no strip) via a MemoryStream.
    /// Returns <c>false</c> when the row is missing or the column is NULL (including unset), and <c>true</c> when data was written.
    /// </summary>
    protected async Task<bool> ReadUnboundedBinaryColumnAsync(
        string propertyName,
        TKey id,
        Stream destination,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(destination);

        var column = EntitySaveMetadata.For(typeof(TEntity)).ColumnByPropertyName(propertyName);
        var value = Store.ReadColumnValue(typeof(TEntity), NormalizeKey(id), column, out var rowExists);

        if (!rowExists)
        {
            return false;
        }

        // Open value objects to their underlying value (when the excluded column is a VO).
        value = value is IValueObjectCore vo ? vo.UnderlyingValue : value;

        if (value is not byte[] bytes)
        {
            // Column NULL (or unset) writes nothing.
            return false;
        }

        await destination.WriteAsync(bytes, cancellationToken).ConfigureAwait(false);
        return true;
    }

    /// <summary>
    /// Writes an unbounded binary column (excluded column) by primary key from a stream (in-memory parity). When
    /// <paramref name="source"/> is <c>null</c>, the column is set to NULL. A stream that is not <c>CanSeek</c> requires
    /// <paramref name="length"/>. The store's actual entity is not mutated directly; a clone is written back instead.
    /// Returns <c>true</c> when updated and <c>false</c> when the row was not found.
    /// </summary>
    protected async Task<bool> WriteUnboundedBinaryColumnAsync(
        string propertyName,
        TKey id,
        Stream? source,
        long? length = null,
        CancellationToken cancellationToken = default
    )
    {
        var column = EntitySaveMetadata.For(typeof(TEntity)).ColumnByPropertyName(propertyName);
        object? stored;

        if (source is null)
        {
            stored = null;
        }
        else
        {
            // The CanSeek/length contract validation matches the real database (dialect-neutral parity).
            var payloadLength = UnboundedBinaryColumns.ResolveWriteLength(source, length);

            // In-memory has no real database streaming, so read everything into a byte[] (contract and semantics are identical,
            // including the exact-length check: a stream shorter or longer than the length fails as it does on a real database).
            using var buffer = new MemoryStream();
            await UnboundedBinaryColumns.WithExactLength(source, payloadLength).CopyToAsync(
                buffer,
                UnboundedBinaryColumns.StreamCopyBufferSize,
                cancellationToken
            ).ConfigureAwait(false);
            var bytes = buffer.ToArray();
            stored = SqlValueObjectActivator.Wrap(bytes, column.PropertyType);
        }

        return Store.WriteColumnValue(typeof(TEntity), NormalizeKey(id), column, stored);
    }

    /// <summary>Saves the graph according to RowState (cascading to children by default).</summary>
    /// <remarks>
    /// When save hooks are registered, this runs in 3 phases: (1) traverse the graph outside the lock, fire Before, and build the
    /// skip set; (2) stage the save inside the lock applying the skips and record the (entity, operation) pairs performed;
    /// (3) fire After outside the lock in execution order. After emulates "before commit": nothing it sees has been published
    /// yet, so the entity still carries the row version it was read with. Once every phase has succeeded the staged writes are
    /// published as one unit and the newly assigned versions reach the caller's entities.
    /// Entities whose type has a rowversion column are guarded by <paramref name="mode"/>: updating or deleting a row that
    /// someone else changed first is rejected, both while staging and again when publishing (which is when a row changed
    /// during phase 3 is caught). The save is all-or-nothing because the store is only ever written by the publish step: a
    /// conflict found part-way through, or an exception thrown by After, leaves the store exactly as it was and the caller's
    /// entities holding the versions they had.
    /// </remarks>
    public async Task<int> SaveAsync(
        TEntity entity,
        bool cascadeSave = true,
        bool cascadeDelete = true,
        bool insertWhenUpdateMissing = false,
        ConcurrencyMode mode = ConcurrencyMode.Optimistic,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entity);
        mode = ConcurrencyModes.Validated(mode);

        // Do nothing if the whole graph has no changes (the change check happens exactly once here and is passed to later phases as already verified).
        if (!EntityGraphSaver.HasChanges(entity, cascadeSave))
        {
            return 0;
        }

        return await SaveRootsAsync(
            [entity],
            cascadeSave,
            cascadeDelete,
            insertWhenUpdateMissing,
            mode,
            cancellationToken
        ).ConfigureAwait(false);
    }

    /// <summary>Saves multiple aggregate roots as one unit (atomic processing: all succeed or all roll back).</summary>
    /// <remarks>
    /// The hook firing order is the same 3 phases as the single-root overload (Before pre-pass, save, After post-pass), and roots are processed in the specified order.
    /// Entities whose type has a rowversion column are guarded by <paramref name="mode"/>: updating or deleting a row that
    /// someone else changed first is rejected. All the roots share one staging and are published together, so a conflict found
    /// part-way through, or an exception thrown by After, leaves every root unwritten.
    /// </remarks>
    public async Task<int> SaveAsync(
        IEnumerable<TEntity> entities,
        bool cascadeSave = true,
        bool cascadeDelete = true,
        bool insertWhenUpdateMissing = false,
        ConcurrencyMode mode = ConcurrencyMode.Optimistic,
        CancellationToken cancellationToken = default
    )
    {
        ArgumentNullException.ThrowIfNull(entities);
        mode = ConcurrencyModes.Validated(mode);
        // Target only graphs with changes (the change check happens exactly once here and is passed to later phases as already verified).
        var roots = entities
            .Where(entity => entity is not null && EntityGraphSaver.HasChanges(entity, cascadeSave))
            .ToList();

        if (roots.Count == 0)
        {
            return 0;
        }

        return await SaveRootsAsync(
            roots,
            cascadeSave,
            cascadeDelete,
            insertWhenUpdateMissing,
            mode,
            cancellationToken
        ).ConfigureAwait(false);
    }

    /// <summary>The 3 phases both <c>SaveAsync</c> overloads share, over roots already known to have changes (see the single-root overload).</summary>
    private async Task<int> SaveRootsAsync(
        IReadOnlyList<TEntity> roots,
        bool cascadeSave,
        bool cascadeDelete,
        bool insertWhenUpdateMissing,
        ConcurrencyMode mode,
        CancellationToken cancellationToken
    )
    {
        // Copy-on-write staging shared by every root, so the whole call is one all-or-nothing unit: every write goes here and
        // reaches the store only once the last phase has succeeded.
        var staging = new InMemorySaveStaging();

        // If hooks are registered, build a session that supplies a context participating in the in-progress store write.
        var hooks =
            _saveHooks is null
                ? null
                : new SaveHookSession(
                    _saveHooks,
                    e => new InMemorySaveHookContext(Store, e.GetType(), staging)
                );

        // Phase 1 (outside the lock): traverse the graphs of all roots in the same order as Save, fire Before, and build the skip set.
        if (hooks is not null)
        {
            foreach (var entity in roots)
            {
                await InMemoryCascade.InvokeBeforeGraphAsync(
                    entity,
                    hooks,
                    cascadeSave,
                    cascadeDelete,
                    cancellationToken,
                    changesAlreadyVerified: true
                ).ConfigureAwait(false);
            }
        }

        // Phase 2 (inside the lock): stage all roots applying the skips and record the (entity, operation) pairs performed.
        var records =
            hooks is null ? null : new List<(EntityBaseCore Entity, SaveOperation Operation)>();
        var rows = Store.Write(
            scope =>
            {
                var total = 0;

                foreach (var entity in roots)
                {
                    total += InMemoryCascade.Save(
                        entity,
                        scope,
                        cascadeSave,
                        cascadeDelete,
                        insertWhenUpdateMissing,
                        mode,
                        hooks,
                        records,
                        changesAlreadyVerified: true
                    );
                }

                return total;
            },
            staging
        );

        // Phase 3 (outside the lock): fire After in execution order. An exception here leaves the staging unpublished, so the
        // "row written but the hook's follow-up failed" half state cannot survive.
        if (hooks is not null)
        {
            foreach (var (recordEntity, operation) in records!)
            {
                await hooks.InvokeAfterAsync(recordEntity, operation, cancellationToken).ConfigureAwait(false);
            }
        }

        // Every phase succeeded, so the staged writes become visible as one unit and hand their row versions to the caller.
        Store.Publish(staging, mode);

        // Finalize the saved graphs as Unchanged (skipped rows are left as they are).
        foreach (var entity in roots)
        {
            EntityGraphSaver.AcceptChanges(entity, cascadeSave, hooks?.Skipped);
        }

        return rows;
    }

    /// <summary>Raw SQL cannot run in memory.</summary>
    public Task<IReadOnlyList<TEntity>> QueryBySqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    ) => throw new NotSupportedException(RawSqlNotSupported);

    /// <summary>Raw SQL cannot run in memory.</summary>
    public Task<int> ExecuteSqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    ) => throw new NotSupportedException(RawSqlNotSupported);

    /// <summary>Raw SQL cannot run in memory.</summary>
    public Task<TResult?> ExecuteScalarSqlAsync<TResult>(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    ) => throw new NotSupportedException(RawSqlNotSupported);

    /// <summary>Normalizes the primary key argument (TKey) into a dictionary key (value objects are opened to their underlying value).</summary>
    private static object NormalizeKey(TKey id)
    {
        object? raw = id is IValueObjectCore vo ? vo.UnderlyingValue : id;

        return raw
            ?? throw new ArgumentNullException(nameof(id), "The primary key must not be null.");
    }
}

/// <summary>In-memory context passed to a save hook's After that participates in the in-progress store write (created bound to an entity type).</summary>
/// <remarks>
/// Excluded-column binary writes are applied to the store with the same Stream-to-byte[] conversion as the existing in-memory
/// stream accessors (strictly following the <c>ResolveWriteLength</c> contract validation and the clone/Put semantics). Raw SQL
/// cannot run in memory and throws <see cref="NotSupportedException"/>. Writes made here join the save's staging, so they build
/// on what the save has already staged for the row, become visible with it, and never reach the store if a later After throws.
/// </remarks>
internal sealed class InMemorySaveHookContext(
    InMemoryDataStore store,
    Type entityType,
    InMemorySaveStaging staging
) : ISaveHookContext
{
    private readonly InMemoryDataStore _store = store;
    private readonly Type _entityType = entityType;
    private readonly InMemorySaveStaging _staging = staging;

    /// <summary>Raw SQL cannot run in memory (switch to a real database repository, or handle it outside the hook).</summary>
    public Task<int> ExecuteSqlAsync(
        string sql,
        object? parameters = null,
        CancellationToken cancellationToken = default
    ) =>
        throw new NotSupportedException(
            "The in-memory repository cannot execute raw SQL. Switch to a real database repository."
        );

    /// <summary>Stream-writes an unbounded binary (excluded) column into the in-progress store write (parity with the real database's streaming).</summary>
    public async Task<bool> WriteBinaryColumnAsync(
        string propertyName,
        object key,
        Stream? source,
        long? length = null,
        CancellationToken cancellationToken = default
    )
    {
        var column = EntitySaveMetadata.For(_entityType).ColumnByPropertyName(propertyName);
        object? stored;

        if (source is null)
        {
            stored = null;
        }
        else
        {
            // The CanSeek/length contract validation matches the real database (dialect-neutral parity).
            var payloadLength = UnboundedBinaryColumns.ResolveWriteLength(source, length);

            // In-memory has no real database streaming, so read everything into a byte[] (contract and semantics are identical,
            // including the exact-length check: a stream shorter or longer than the length fails as it does on a real database).
            using var buffer = new MemoryStream();
            await UnboundedBinaryColumns.WithExactLength(source, payloadLength).CopyToAsync(
                buffer,
                UnboundedBinaryColumns.StreamCopyBufferSize,
                cancellationToken
            ).ConfigureAwait(false);
            var bytes = buffer.ToArray();
            stored = SqlValueObjectActivator.Wrap(bytes, column.PropertyType);
        }

        return _store.WriteColumnValue(_entityType, NormalizeKey(key), column, stored, _staging);
    }

    /// <summary>Normalizes the primary key (object) into a dictionary key (value objects are opened to their underlying value).</summary>
    private static object NormalizeKey(object key)
    {
        object? raw = key is IValueObjectCore vo ? vo.UnderlyingValue : key;

        return raw
            ?? throw new ArgumentNullException(nameof(key), "The primary key must not be null.");
    }
}

