/// <summary>Seeder that loads deterministic sample data into the in-memory store (up to 3 rows per entity).</summary>
/// <remarks>
/// <para>
/// Values are generated deterministically from the column metadata and the column's role: a primary-key or UNIQUE
/// column gets a different value on every row (int keys = 1,2,3; string keys = "{COLUMN NAME}-00n", shortened before the
/// row number when the column is too short; Guids are deterministic from a fixed seed), a foreign-key column takes the
/// value of the column it refers to on the same row, so row n of a child refers to row n of its parent, and any other
/// column gets a type-based fixed value ("{column name} n" for strings). Nullable columns get null in the third row.
/// </para>
/// <para>
/// An entity whose primary key or UNIQUE constraint cannot take three different sample values (a NOT NULL bool, for
/// one) is seeded with fewer rows, and so is a child that refers to it, so that every key and UNIQUE constraint holds and
/// every foreign key refers to a row that exists.
/// </para>
/// </remarks>
public static class InMemorySampleData
{
    /// <summary>The most rows seeded per entity (an entity whose keys cannot take that many different values gets fewer).</summary>
    public const int RowsPerEntity = 3;

    /// <summary>Seeds sample data for all entities (in parent-to-child FK dependency order).</summary>
    public static void Seed(InMemoryDataStore store)
    {
        ArgumentNullException.ThrowIfNull(store);
        SeedCustomerEntity(store);
        SeedOrderEntity(store);
        SeedOrderLineEntity(store);

    }

    /// <summary>Seeds sample data for customers.</summary>
    private static void SeedCustomerEntity(InMemoryDataStore store)
    {
        for (var index = 1; index <= RowsPerEntity; index++)
        {
            var entity = new CustomerEntity
            {
                CustomerId = CreateSampleValue<CustomerIdValue, int>("CustomerEntity.CustomerId", index),
                Name = CreateSampleValue<NameValue, string>("CustomerEntity.Name", $"name {index}"),
                Note = index == 3 ? null : CreateSampleValue<NoteValue, string>("CustomerEntity.Note", $"note {index}"),
                ReferrerId = index == 3 ? null : CreateSampleValue<CustomerIdValue, int>("CustomerEntity.ReferrerId", index),
            };
            entity.MarkAdded();
            store.Put(entity);
            entity.MarkUnchanged();
        }
    }

    /// <summary>Seeds sample data for orders.</summary>
    private static void SeedOrderEntity(InMemoryDataStore store)
    {
        for (var index = 1; index <= RowsPerEntity; index++)
        {
            var entity = new OrderEntity
            {
                OrderId = CreateSampleValue<OrderIdValue, int>("OrderEntity.OrderId", index),
                CustomerId = CreateSampleValue<CustomerIdValue, int>("OrderEntity.CustomerId", index),
                Amount = CreateSampleValue<AmountValue, decimal>("OrderEntity.Amount", index * 100.05m),
                Memo = index == 3 ? null : CreateSampleValue<MemoValue, string>("OrderEntity.Memo", $"memo {index}"),
                OrderedAt = index == 3 ? null : CreateSampleValue<OrderedAtValue, DateTime>("OrderEntity.OrderedAt", new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc).AddDays(index)),
                IsPaid = CreateSampleValue<IsPaidValue, bool>("OrderEntity.IsPaid", index % 2 == 1),
                Payload = index == 3 ? null : CreateSampleValue<PayloadValue, byte[]>("OrderEntity.Payload", new byte[] { (byte)index, (byte)(index + 1), (byte)(index + 2) }),
                Thumb = CreateSampleValue<ThumbValue, byte[]>("OrderEntity.Thumb", new byte[] { (byte)index, (byte)(index + 1), (byte)(index + 2) }),
            };
            entity.MarkAdded();
            store.Put(entity);
            entity.MarkUnchanged();
        }
    }

    /// <summary>Seeds sample data for order_lines.</summary>
    private static void SeedOrderLineEntity(InMemoryDataStore store)
    {
        for (var index = 1; index <= RowsPerEntity; index++)
        {
            var entity = new OrderLineEntity
            {
                LineId = CreateSampleValue<LineIdValue, int>("OrderLineEntity.LineId", index),
                OrderId = CreateSampleValue<OrderIdValue, int>("OrderLineEntity.OrderId", index),
                Item = CreateSampleValue<ItemValue, string>("OrderLineEntity.Item", $"item {index}"),
                Quantity = CreateSampleValue<QuantityValue, int>("OrderLineEntity.Quantity", index * 10),
                Discount = index == 3 ? null : CreateSampleValue<DiscountValue, decimal>("OrderLineEntity.Discount", index * 100.05m),
            };
            entity.MarkAdded();
            store.Put(entity);
            entity.MarkUnchanged();
        }
    }

    /// <summary>Creates a value object for seeding, so a rejected sample value reports what was assigned where and how to proceed.</summary>
    /// <remarks>
    /// The generated sample values satisfy the constraints declared in the diagram (maximum length, decimal
    /// precision/scale), but they cannot know the rules a hand-written OnValidate - or a hand-written value object -
    /// adds. Such a rejection is not something better sample values could avoid; what matters is that the failure,
    /// surfacing from inside AddGeneratedInMemoryRepositories, immediately names the property, the value, and the way
    /// out (seedSampleData: false). The original validation failure travels as the inner exception.
    /// </remarks>
    private static TVo CreateSampleValue<TVo, TValue>(string target, TValue value)
        where TVo : IValueObject<TVo, TValue>
    {
        try
        {
            return TVo.Create(value);
        }
        catch (ValueObjectValidationException error)
        {
            throw new InvalidOperationException(
                FormattableString.Invariant(
                    $"Seeding sample data failed: cannot assign \"{value}\" to {target} ({error.Message}). "
                )
                    + "A user-defined validation rule rejects the generated sample value, and sample values cannot know such rules. "
                    + "Register with AddGeneratedInMemoryRepositories(seedSampleData: false) and insert your own data instead.",
                error
            );
        }
    }
}

/// <summary>Extensions that register the in-memory repositories with the DI container.</summary>
public static class GeneratedInMemoryRepositoryServiceCollectionExtensions
{
    /// <summary>Registers the in-memory data store (singleton) and each in-memory repository (scoped).</summary>
    /// <remarks>
    /// There is no keyed overload: keyed registration exists so that one process can write to several databases through
    /// the same contracts, which is a multi-target concern of the dialect-specific extensions.
    /// </remarks>
    /// <param name="services">The service collection to register into.</param>
    /// <param name="seedSampleData">When true (the default), the store is registered already seeded with the deterministic sample data of <see cref="InMemorySampleData"/>.</param>
    public static IServiceCollection AddGeneratedInMemoryRepositories(
        this IServiceCollection services,
        bool seedSampleData = true
    )
    {
        ArgumentNullException.ThrowIfNull(services);

        var store = new InMemoryDataStore();

        if (seedSampleData)
        {
            InMemorySampleData.Seed(store);
        }

        services.AddSingleton(store);

        // Register the save hook registry by default (a complete no-op if no ISaveHook<T> is registered).
        services.TryAddScoped<ISaveHookRegistry>(provider => new ServiceProviderSaveHookRegistry(
            provider
        ));

        // Both contracts are meant to hand back one repository per scope, so the remote surface forwards to the
        // full-featured registration instead of being registered on its own
        void AddRepository<TContract, TRemote, TImplementation>()
            where TContract : class, TRemote
            where TRemote : class
            where TImplementation : class, TContract
        {
            services.AddScoped<TContract, TImplementation>();
            services.AddScoped<TRemote>(provider => provider.GetRequiredService<TContract>());
        }

        AddRepository<ICustomerRepository, ICustomerRemoteRepository, InMemoryCustomerRepository>();
        AddRepository<IOrderRepository, IOrderRemoteRepository, InMemoryOrderRepository>();
        AddRepository<IOrderLineRepository, IOrderLineRemoteRepository, InMemoryOrderLineRepository>();

        return services;
    }
}

/// <summary>
/// EF Core DbContext that connects to an existing schema.
/// </summary>
/// <remarks>
/// Schema creation (Migrations / EnsureCreated) is out of scope. This context only holds the configuration
/// needed to map existing entities to existing tables for reading and writing. Column database types
/// (HasColumnType) are not baked in and are left to DDL generation.
/// </remarks>
public partial class QuickErDbContext : DbContext
{
    /// <summary>Initializes the DbContext with the given options.</summary>
    public QuickErDbContext(DbContextOptions<QuickErDbContext> options)
        : base(options) { }

    /// <summary>Adds an extension that translates value object string methods (Contains/StartsWith/EndsWith and .Value) into SQL.</summary>
    /// <remarks>
    /// Value objects are projected onto string columns by a converter (v =&gt; v.Value), but by default EF Core
    /// cannot translate the <c>Contains</c> of a string value object and similar members, so the query fails.
    /// <see cref="ValueObjectTranslationDbContextOptionsExtension"/> is plugged in to translate these into LIKE / plain string columns.
    /// </remarks>
    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        base.OnConfiguring(optionsBuilder);

        if (optionsBuilder.Options.FindExtension<ValueObjectTranslationDbContextOptionsExtension>() is null)
        {
            ((IDbContextOptionsBuilderInfrastructure)optionsBuilder).AddOrUpdateExtension(
                new ValueObjectTranslationDbContextOptionsExtension()
            );
        }
    }

    /// <summary>DbSet for CustomerEntity.</summary>
    public DbSet<CustomerEntity> Customers => Set<CustomerEntity>();

    /// <summary>DbSet for OrderEntity.</summary>
    public DbSet<OrderEntity> Orders => Set<OrderEntity>();

    /// <summary>DbSet for OrderLineEntity.</summary>
    public DbSet<OrderLineEntity> OrderLines => Set<OrderLineEntity>();

    /// <summary>Configures the table, keys, columns, and relationships for each entity using the Fluent API.</summary>
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<CustomerEntity>(entity =>
        {
            entity.ToTable("customers");
            entity.HasKey(e => e.CustomerId);
            entity.Ignore(e => e.RowState);
            entity.Ignore(e => e.IsAdded);
            entity.Ignore(e => e.IsUpdated);
