            entity.Ignore(e => e.HasChanges);
            entity.Property(e => e.CustomerId).HasColumnName("customer_id").IsRequired().HasConversion(v => v!.Value, v => CustomerIdValue.Create(v!));
            entity.Property(e => e.Name).HasColumnName("name").IsRequired().HasMaxLength(50).HasConversion(v => v!.Value, v => NameValue.Create(v!));
            entity.Property(e => e.Note).HasColumnName("note").HasMaxLength(100).HasConversion(v => v!.Value, v => NoteValue.Create(v!));
            entity.Property(e => e.ReferrerId).HasColumnName("referrer_id").HasConversion(v => v!.Value, v => CustomerIdValue.Create(v!));
            entity
                .HasMany(e => e.Orders)
                .WithOne(e => e.Customer)
                .HasForeignKey(e => e.CustomerId)
                .OnDelete(DeleteBehavior.Cascade);
            entity
                .HasMany(e => e.Customers)
                .WithOne()
                .HasForeignKey(e => e.ReferrerId)
                .OnDelete(DeleteBehavior.NoAction);
        });

        modelBuilder.Entity<OrderEntity>(entity =>
        {
            entity.ToTable("orders");
            entity.HasKey(e => e.OrderId);
            entity.Ignore(e => e.RowState);
            entity.Ignore(e => e.IsAdded);
            entity.Ignore(e => e.IsUpdated);
            entity.Ignore(e => e.IsRemoved);
            entity.Ignore(e => e.HasChanges);
            entity.Property(e => e.OrderId).HasColumnName("order_id").IsRequired().HasConversion(v => v!.Value, v => OrderIdValue.Create(v!));
            entity.Property(e => e.CustomerId).HasColumnName("customer_id").IsRequired().HasConversion(v => v!.Value, v => CustomerIdValue.Create(v!));
            entity.Property(e => e.Amount).HasColumnName("amount").IsRequired().HasPrecision(10, 2).HasConversion(v => v!.Value, v => AmountValue.Create(v!));
            entity.Property(e => e.Memo).HasColumnName("memo").HasMaxLength(100).HasConversion(v => v!.Value, v => MemoValue.Create(v!));
