            entity.Property(e => e.IsPaid).HasColumnName("is_paid").IsRequired().HasConversion(v => v!.Value, v => IsPaidValue.Create(v!));
            entity.Property(e => e.Payload).HasColumnName("payload").HasConversion(v => v!.Value, v => PayloadValue.Create(v!));
            entity.Property(e => e.Thumb).HasColumnName("thumb").IsRequired().HasConversion(v => v!.Value, v => ThumbValue.Create(v!));
            entity
                .HasMany(e => e.OrderLines)
                .WithOne(e => e.Order)
