            entity.Property(e => e.Quantity).HasColumnName("quantity").IsRequired().HasConversion(v => v!.Value, v => QuantityValue.Create(v!));
            entity.Property(e => e.Discount).HasColumnName("discount").HasPrecision(5, 2).HasConversion(v => v!.Value, v => DiscountValue.Create(v!));
        });

        OnModelCreatingPartial(modelBuilder);
    }

